sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {

    var c = this;


    /* =====================================================
       SIDEBAR
       ===================================================== */

    c.sidebarOpen = true;


    c.toggleSidebar = function() {

        c.sidebarOpen =
            !c.sidebarOpen;

    };


    c.closeSidebar = function() {

        c.sidebarOpen = false;

    };





    /* =====================================================
       DRAWERS
       ===================================================== */

    c.analyticsOpen = false;

    c.studentsOpen = false;

    c.selectedAssessment = null;

    c.studentDetail = null;

    c.formOpen = false;

    c.loading = false;

    c.saving = false;

    c.formError = '';


    c.openAnalytics = function() {

        c.studentsOpen = false;

        c.selectedAssessment = null;

        c.analyticsOpen = true;

        c.rebuildAnalytics();

    };


    c.closeAnalytics = function() {

        c.analyticsOpen = false;

    };


    c.openStudents = function() {

        c.analyticsOpen = false;

        c.selectedAssessment = null;

        c.studentsOpen = true;

        c.studentPage = 1;

        c.rebuildStudentFilterChoices();

        c.rebuildStudentView();

    };


    c.closeStudents = function() {

        c.studentsOpen = false;

    };


    c.closeAllDrawers = function() {

        c.analyticsOpen = false;

        c.studentsOpen = false;

        c.selectedAssessment = null;

    };


    /* =====================================================
       FILTERS
       ===================================================== */

    c.filters = {

        search: '',

        company: 'all',

        result: 'all',

        type: 'all',

        status: 'all'

    };


    c.studentFilters = {

        search: '',

        application: 'all',

        interview: 'all',

        offer: 'all',

        assessment: 'all'

    };


    /* =====================================================
       PAGINATION
       ===================================================== */

    c.pageSize = 20;

    c.currentPage = 1;

    c.totalPages = 1;

    c.firstRecord = 0;

    c.lastRecord = 0;

    c.filteredRows = [];

    c.pagedRows = [];


    c.studentPageSize = 10;

    c.studentPage = 1;

    c.studentTotalPages = 1;

    c.studentFirstRecord = 0;

    c.studentLastRecord = 0;

    c.filteredStudents = [];

    c.pagedStudents = [];


    /* =====================================================
       ANALYTICS
       ===================================================== */

    c.analytics = {

        assessmentCount: 0,

        applicationCount: 0,

        uniqueStudents: 0,

        assessedStudents: 0,

        coverageRate: 0,

        passed: 0,

        failed: 0,

        pending: 0,

        interviewCount: 0,

        offerCount: 0,

        averageScore: 0,

        passRate: 0,

        pendingRate: 0,

        opportunityCount: 0,

        resultPercent: {

            passed: 0,

            failed: 0,

            pending: 0

        },

        resultChart: [],

        pipelineChart: [],

        typeChart: [],

        scoreBands: [],

        opportunityChart: []

    };


    c.selectedCompanyName =
        'All Companies';


    /* =====================================================
       HELPERS
       ===================================================== */

    function lower(
        value
    ) {

        return String(
            value || ''
        )
        .replace(
            /^\s+|\s+$/g,
            ''
        )
        .toLowerCase();

    }


    function sameChoice(
        selected,
        value,
        label
    ) {

        if (
            selected === 'all'
        ) {

            return true;

        }


        var s =
            lower(
                selected
            );


        return (
            s === lower(value)
        ) ||
        (
            s === lower(label)
        );

    }


    function hasOwn(
        object,
        key
    ) {

        return Object.prototype.hasOwnProperty.call(
            object,
            key
        );

    }


    /* =====================================================
       ASSESSMENT MATCHING
       ===================================================== */

    c.matchesAssessment =
        function(
            row
        ) {


            if (
                c.filters.company !==
                'all'
            ) {

                if (
                    lower(
                        row.company_id
                    ) !==
                    lower(
                        c.filters.company
                    )
                ) {

                    return false;

                }

            }


            if (
                c.filters.result !==
                'all'
            ) {

                if (
                    !sameChoice(
                        c.filters.result,
                        row.result_value,
                        row.result
                    )
                ) {

                    return false;

                }

            }


            if (
                c.filters.type !==
                'all'
            ) {

                if (
                    !sameChoice(
                        c.filters.type,
                        row.assessment_type_value,
                        row.assessment_type
                    )
                ) {

                    return false;

                }

            }


            if (
                c.filters.status !==
                'all'
            ) {

                if (
                    !sameChoice(
                        c.filters.status,
                        row.status_value,
                        row.status
                    )
                ) {

                    return false;

                }

            }


            var search =
                lower(
                    c.filters.search
                );


            if (
                search
            ) {

                var searchable = [

                    row.assessment_id,

                    row.assessment_name,

                    row.assessment_date,

                    row.assessment_type,

                    row.company_name,

                    row.company_id,

                    row.opportunity,

                    row.opportunity_title,

                    row.result,

                    row.status,

                    row.remarks,

                    row.student_name,

                    row.student_id

                ].join(' ');


                if (
                    lower(
                        searchable
                    ).indexOf(
                        search
                    ) === -1
                ) {

                    return false;

                }

            }


            return true;

        };


    /* =====================================================
       TABLE VIEW
       ===================================================== */

    c.rebuildView =
        function() {

            var source =
                c.data.rows ||
                [];


            var filtered = [];


            var i;


            for (
                i = 0;
                i < source.length;
                i++
            ) {

                if (
                    c.matchesAssessment(
                        source[i]
                    )
                ) {

                    filtered.push(
                        source[i]
                    );

                }

            }


            filtered.sort(
                function(
                    a,
                    b
                ) {

                    return String(
                        b.assessment_date_raw ||
                        ''
                    )
                    .localeCompare(
                        String(
                            a.assessment_date_raw ||
                            ''
                        )
                    );

                }
            );


            c.filteredRows =
                filtered;


            c.totalPages =
                Math.max(
                    1,
                    Math.ceil(
                        filtered.length /
                        c.pageSize
                    )
                );


            if (
                c.currentPage >
                c.totalPages
            ) {

                c.currentPage =
                    c.totalPages;

            }


            var start =
                (
                    c.currentPage -
                    1
                ) *
                c.pageSize;


            var end =
                start +
                c.pageSize;


            c.pagedRows =
                filtered.slice(
                    start,
                    end
                );


            c.firstRecord =
                filtered.length
                    ? start + 1
                    : 0;


            c.lastRecord =
                filtered.length
                    ? Math.min(
                        end,
                        filtered.length
                      )
                    : 0;

        };





    /* =====================================================
       COMPANY NAME
       ===================================================== */

    c.updateCompanyName =
        function() {

            if (
                c.filters.company ===
                'all'
            ) {

                c.selectedCompanyName =
                    'All Companies';

                return;

            }


            var choices =
                c.data.companyChoices ||
                [];


            var i;


            for (
                i = 0;
                i < choices.length;
                i++
            ) {

                if (
                    String(
                        choices[i].value
                    ) ===
                    String(
                        c.filters.company
                    )
                ) {

                    c.selectedCompanyName =
                        choices[i].label;

                    return;

                }

            }


            c.selectedCompanyName =
                c.filters.company;

        };


    /* =====================================================
       FILTERED STUDENTS
       ===================================================== */

    c.getFilteredStudentRows =
        function() {

            var source =
                c.data.studentRows ||
                [];


            var result = [];


            var i;


            for (
                i = 0;
                i < source.length;
                i++
            ) {

                var row =
                    source[i];


                if (
                    c.filters.company !==
                    'all' &&
                    lower(
                        row.company_id
                    ) !==
                    lower(
                        c.filters.company
                    )
                ) {

                    continue;

                }


                var globalSearch =
                    lower(
                        c.filters.search
                    );


                if (
                    globalSearch
                ) {

                    var text = [

                        row.student_name,

                        row.student_id,

                        row.company_name,

                        row.opportunity,

                        row.application_status,

                        row.interview_status,

                        row.offer_status,

                        row.assessment_result

                    ].join(' ');


                    if (
                        lower(
                            text
                        ).indexOf(
                            globalSearch
                        ) === -1
                    ) {

                        continue;

                    }

                }


                if (
                    c.filters.result !==
                    'all' &&
                    !sameChoice(
                        c.filters.result,
                        row.assessment_result_value,
                        row.assessment_result
                    )
                ) {

                    continue;

                }


                if (
                    c.filters.type !==
                    'all' &&
                    !sameChoice(
                        c.filters.type,
                        row.assessment_type_value,
                        row.assessment_type
                    )
                ) {

                    continue;

                }


                if (
                    c.filters.status !==
                    'all' &&
                    !sameChoice(
                        c.filters.status,
                        row.assessment_status_value,
                        row.assessment_status
                    )
                ) {

                    continue;

                }


                result.push(
                    row
                );

            }


            return result;

        };


    /* =====================================================
       STUDENT VIEW
       ===================================================== */

    c.rebuildStudentView =
        function() {

            var source =
                c.getFilteredStudentRows();


            var result = [];


            var i;


            for (
                i = 0;
                i < source.length;
                i++
            ) {

                var row =
                    source[i];


                var search =
                    lower(
                        c.studentFilters.search
                    );


                if (
                    search
                ) {

                    var text = [

                        row.student_name,

                        row.student_id,

                        row.company_name,

                        row.opportunity

                    ].join(' ');


                    if (
                        lower(text)
                        .indexOf(search)
                        === -1
                    ) {

                        continue;

                    }

                }


                if (
                    c.studentFilters.application !==
                    'all' &&
                    lower(
                        row.application_status
                    ) !==
                    lower(
                        c.studentFilters.application
                    )
                ) {

                    continue;

                }


                if (
                    c.studentFilters.interview !==
                    'all' &&
                    lower(
                        row.interview_status
                    ) !==
                    lower(
                        c.studentFilters.interview
                    )
                ) {

                    continue;

                }


                if (
                    c.studentFilters.offer !==
                    'all' &&
                    lower(
                        row.offer_status
                    ) !==
                    lower(
                        c.studentFilters.offer
                    )
                ) {

                    continue;

                }


                if (
                    c.studentFilters.assessment !==
                    'all'
                ) {

                    if (
                        lower(
                            row.assessment_result ||
                            'Not Assessed'
                        ) !==
                        lower(
                            c.studentFilters.assessment
                        )
                    ) {

                        continue;

                    }

                }


                result.push(
                    row
                );

            }


            c.filteredStudents =
                result;


            c.studentTotalPages =
                Math.max(
                    1,
                    Math.ceil(
                        result.length /
                        c.studentPageSize
                    )
                );


            if (
                c.studentPage >
                c.studentTotalPages
            ) {

                c.studentPage =
                    c.studentTotalPages;

            }


            var start =
                (
                    c.studentPage -
                    1
                ) *
                c.studentPageSize;


            var end =
                start +
                c.studentPageSize;


            c.pagedStudents =
                result.slice(
                    start,
                    end
                );


            c.studentFirstRecord =
                result.length
                    ? start + 1
                    : 0;


            c.studentLastRecord =
                result.length
                    ? Math.min(
                        end,
                        result.length
                      )
                    : 0;

        };


    c.goToStudentPage =
        function(
            page
        ) {

            page =
                Number(page);


            if (
                page < 1 ||
                page > c.studentTotalPages
            ) {

                return;

            }


            c.studentPage =
                page;


            c.rebuildStudentView();

        };


    /* =====================================================
       STUDENT FILTER CHOICES
       ===================================================== */

    c.rebuildStudentFilterChoices =
        function() {

            var rows =
                c.getFilteredStudentRows();


            var maps = {

                application: {},

                interview: {},

                offer: {},

                assessment: {}

            };


            var i;


            for (
                i = 0;
                i < rows.length;
                i++
            ) {

                var row =
                    rows[i];


                if (
                    row.application_status
                ) {

                    maps.application[
                        row.application_status
                    ] = true;

                }


                if (
                    row.interview_status
                ) {

                    maps.interview[
                        row.interview_status
                    ] = true;

                }


                if (
                    row.offer_status
                ) {

                    maps.offer[
                        row.offer_status
                    ] = true;

                }


                if (
                    row.assessment_result
                ) {

                    maps.assessment[
                        row.assessment_result
                    ] = true;

                }

            }


            c.data.studentFilterChoices = {

                application:
                    Object.keys
                        ? Object.keys(
                            maps.application
                          )
                        : [],

                interview:
                    Object.keys
                        ? Object.keys(
                            maps.interview
                          )
                        : [],

                offer:
                    Object.keys
                        ? Object.keys(
                            maps.offer
                          )
                        : [],

                assessment:
                    Object.keys
                        ? Object.keys(
                            maps.assessment
                          )
                        : []

            };

        };


    /* =====================================================
       ANALYTICS
       ===================================================== */

    c.rebuildAnalytics =
        function() {

            var rows =
                c.filteredRows ||
                [];


            var passed = 0;
            var failed = 0;
            var pending = 0;

            var scoreTotal = 0;
            var scoreCount = 0;


            var studentMap = {};
            var assessedMap = {};
            var typeMap = {};
            var opportunityMap = {};


            var i;


            for (
                i = 0;
                i < rows.length;
                i++
            ) {

                var row =
                    rows[i];


                var result =
                    lower(
                        row.result
                    );


                if (
                    result === 'passed'
                ) {

                    passed++;

                } else if (
                    result === 'failed'
                ) {

                    failed++;

                } else if (
                    result === 'pending'
                ) {

                    pending++;

                }


                if (
                    row.student
                ) {

                    studentMap[
                        row.student
                    ] = true;

                    assessedMap[
                        row.student
                    ] = true;

                }


                if (
                    row.maximum_score > 0
                ) {

                    scoreTotal +=
                        Number(
                            row.scorePercentage ||
                            0
                        );

                    scoreCount++;

                }


                var type =
                    row.assessment_type ||
                    'Other';


                typeMap[type] =
                    (
                        typeMap[type] ||
                        0
                    ) + 1;


                var opportunity =
                    row.opportunity ||
                    row.opportunity_title ||
                    'Opportunity';


                opportunityMap[
                    opportunity
                ] =
                    (
                        opportunityMap[
                            opportunity
                        ] ||
                        0
                    ) + 1;

            }


            var students =
                c.getFilteredStudentRows();


            var applications = 0;

            var applicationStudents = {};

            var interviewCount = 0;
            var offerCount = 0;


            for (
                i = 0;
                i < students.length;
                i++
            ) {

                var s =
                    students[i];


                if (
                    s.has_application
                ) {

                    applications++;

                }


                if (
                    s.student_sys_id
                ) {

                    applicationStudents[
                        s.student_sys_id
                    ] = true;

                }


                if (
                    c.isInterviewActivity(
                        s.interview_status
                    )
                ) {

                    interviewCount++;

                }


                if (
                    c.isOfferActivity(
                        s.offer_status
                    )
                ) {

                    offerCount++;

                }

            }


            var uniqueStudents =
                Object.keys
                    ? Object.keys(
                        applicationStudents
                      ).length
                    : 0;


            var assessedStudents =
                Object.keys
                    ? Object.keys(
                        assessedMap
                      ).length
                    : 0;


            var averageScore =
                scoreCount
                    ? Math.round(
                        scoreTotal /
                        scoreCount
                      )
                    : 0;


            var coverage =
                uniqueStudents
                    ? Math.min(
                        100,
                        Math.round(
                            (
                                assessedStudents /
                                uniqueStudents
                            ) *
                            100
                        )
                      )
                    : 0;


            var resultTotal =
                passed +
                failed +
                pending;


            var passRate =
                resultTotal
                    ? Math.round(
                        (
                            passed /
                            resultTotal
                        ) *
                        100
                      )
                    : 0;


            var pendingRate =
                resultTotal
                    ? Math.round(
                        (
                            pending /
                            resultTotal
                        ) *
                        100
                      )
                    : 0;


            var resultPercent = {

                passed:
                    resultTotal
                        ? Math.round(
                            (
                                passed /
                                resultTotal
                            ) * 100
                          )
                        : 0,

                failed:
                    resultTotal
                        ? Math.round(
                            (
                                failed /
                                resultTotal
                            ) * 100
                          )
                        : 0,

                pending:
                    resultTotal
                        ? Math.round(
                            (
                                pending /
                                resultTotal
                            ) * 100
                          )
                        : 0

            };


            /* TYPE */

            var typeChart = [];

            var typeTotal = 0;

            var key;


            for (
                key in typeMap
            ) {

                if (
                    hasOwn(
                        typeMap,
                        key
                    )
                ) {

                    typeTotal +=
                        typeMap[key];

                }

            }


            for (
                key in typeMap
            ) {

                if (
                    hasOwn(
                        typeMap,
                        key
                    )
                ) {

                    typeChart.push({

                        label:
                            key,

                        count:
                            typeMap[key],

                        percent:
                            typeTotal
                                ? Math.round(
                                    (
                                      typeMap[key] /
                                      typeTotal
                                    ) *
                                    100
                                  )
                                : 0

                    });

                }

            }


            typeChart.sort(
                function(
                    a,
                    b
                ) {

                    return b.count -
                        a.count;

                }
            );


            /* OPPORTUNITY */

            var opportunityChart = [];

            var highestOpportunity = 0;


            for (
                key in opportunityMap
            ) {

                if (
                    hasOwn(
                        opportunityMap,
                        key
                    )
                ) {

                    highestOpportunity =
                        Math.max(
                            highestOpportunity,
                            opportunityMap[key]
                        );


                    opportunityChart.push({

                        label:
                            key,

                        assessments:
                            opportunityMap[key]

                    });

                }

            }


            opportunityChart.sort(
                function(
                    a,
                    b
                ) {

                    return b.assessments -
                        a.assessments;

                }
            );


            for (
                i = 0;
                i < opportunityChart.length;
                i++
            ) {

                opportunityChart[i].percent =
                    highestOpportunity
                        ? Math.round(
                            (
                                opportunityChart[i]
                                    .assessments /
                                highestOpportunity
                            ) *
                            100
                          )
                        : 0;

            }


            /* SCORE BANDS */

            var scoreBands = [

                {
                    label: '0-49',
                    count: 0,
                    height: 0
                },

                {
                    label: '50-69',
                    count: 0,
                    height: 0
                },

                {
                    label: '70-84',
                    count: 0,
                    height: 0
                },

                {
                    label: '85-100',
                    count: 0,
                    height: 0
                }

            ];


            var latest = {};


            for (
                i = 0;
                i < rows.length;
                i++
            ) {

                var scoreRow =
                    rows[i];


                var studentKey =
                    scoreRow.student ||
                    scoreRow.student_id ||
                    scoreRow.sys_id;


                latest[
                    studentKey
                ] =
                    scoreRow;

            }


            for (
                key in latest
            ) {

                if (
                    !hasOwn(
                        latest,
                        key
                    )
                ) {

                    continue;

                }


                var score =
                    Number(
                        latest[key]
                            .scorePercentage ||
                        0
                    );


                if (
                    score <= 49
                ) {

                    scoreBands[0].count++;

                } else if (
                    score <= 69
                ) {

                    scoreBands[1].count++;

                } else if (
                    score <= 84
                ) {

                    scoreBands[2].count++;

                } else {

                    scoreBands[3].count++;

                }

            }


            var maxBand = 0;


            for (
                i = 0;
                i < scoreBands.length;
                i++
            ) {

                maxBand =
                    Math.max(
                        maxBand,
                        scoreBands[i].count
                    );

            }


            for (
                i = 0;
                i < scoreBands.length;
                i++
            ) {

                scoreBands[i].height =
                    maxBand
                        ? Math.max(
                            3,
                            Math.round(
                                (
                                    scoreBands[i]
                                        .count /
                                    maxBand
                                ) *
                                100
                            )
                          )
                        : 0;

            }


            /* OPPORTUNITY COUNT */

            var opportunityIds = {};


            for (
                i = 0;
                i < rows.length;
                i++
            ) {

                if (
                    rows[i].opportunity_value
                ) {

                    opportunityIds[
                        rows[i].opportunity_value
                    ] = true;

                }

            }


            var opportunityCount =
                Object.keys
                    ? Object.keys(
                        opportunityIds
                      ).length
                    : 0;


            /* FINAL */

            c.analytics = {

                assessmentCount:
                    rows.length,

                applicationCount:
                    applications,

                uniqueStudents:
                    uniqueStudents,

                assessedStudents:
                    assessedStudents,

                coverageRate:
                    coverage,

                passed:
                    passed,

                failed:
                    failed,

                pending:
                    pending,

                interviewCount:
                    interviewCount,

                offerCount:
                    offerCount,

                averageScore:
                    averageScore,

                passRate:
                    passRate,

                pendingRate:
                    pendingRate,

                opportunityCount:
                    opportunityCount,

                resultPercent:
                    resultPercent,

                resultChart: [

                    {
                        label: 'Passed',
                        count: passed,
                        color: '#19a76c'
                    },

                    {
                        label: 'Failed',
                        count: failed,
                        color: '#eb5656'
                    },

                    {
                        label: 'Pending',
                        count: pending,
                        color: '#e5a322'
                    }

                ],

                pipelineChart:
                    c.buildPipeline(
                        applications,
                        interviewCount,
                        offerCount
                    ),

                typeChart:
                    typeChart,

                scoreBands:
                    scoreBands,

                opportunityChart:
                    opportunityChart

            };

        };


    /* =====================================================
       PIPELINE
       ===================================================== */

    c.buildPipeline =
        function(
            applications,
            interviews,
            offers
        ) {

            var max =
                Math.max(
                    applications,
                    interviews,
                    offers,
                    1
                );


            return [

                {
                    label:
                        'Applications',

                    count:
                        applications,

                    percent:
                        Math.round(
                            (
                                applications /
                                max
                            ) *
                            100
                        ),

                    color:
                        '#7040ff'
                },

                {
                    label:
                        'Interview Activity',

                    count:
                        interviews,

                    percent:
                        Math.round(
                            (
                                interviews /
                                max
                            ) *
                            100
                        ),

                    color:
                        '#347fd9'
                },

                {
                    label:
                        'Offers',

                    count:
                        offers,

                    percent:
                        Math.round(
                            (
                                offers /
                                max
                            ) *
                            100
                        ),

                    color:
                        '#19a774'
                }

            ];

        };


    /* =====================================================
       DONUT
       ===================================================== */

    c.getDonutStyle =
        function(
            items
        ) {

            if (
                !items ||
                !items.length
            ) {

                return {
                    background:
                        '#edf1f4'
                };

            }


            var total = 0;


            var i;


            for (
                i = 0;
                i < items.length;
                i++
            ) {

                total +=
                    Number(
                        items[i].count ||
                        0
                    );

            }


            if (
                total <= 0
            ) {

                return {
                    background:
                        '#edf1f4'
                };

            }


            var start = 0;

            var pieces = [];


            for (
                i = 0;
                i < items.length;
                i++
            ) {

                var count =
                    Number(
                        items[i].count ||
                        0
                    );


                if (
                    count <= 0
                ) {

                    continue;

                }


                var end =
                    start +
                    (
                        count /
                        total
                    ) *
                    360;


                pieces.push(
                    items[i].color +
                    ' ' +
                    start +
                    'deg ' +
                    end +
                    'deg'
                );


                start = end;

            }


            return {

                background:
                    pieces.length
                        ? 'conic-gradient(' +
                          pieces.join(',') +
                          ')'
                        : '#edf1f4'

            };

        };


    /* =====================================================
       RESULT / STATUS
       ===================================================== */

    c.getResultClass =
        function(
            result
        ) {

            var value =
                lower(
                    result
                );


            if (
                value === 'passed'
            ) {

                return 'result-passed';

            }


            if (
                value === 'failed'
            ) {

                return 'result-failed';

            }


            if (
                value === 'pending'
            ) {

                return 'result-pending';

            }


            return 'result-other';

        };


    c.getResultIcon =
        function(
            result
        ) {

            var value =
                lower(
                    result
                );


            if (
                value === 'passed'
            ) {

                return 'fa-check';

            }


            if (
                value === 'failed'
            ) {

                return 'fa-times';

            }


            if (
                value === 'pending'
            ) {

                return 'fa-clock-o';

            }


            return 'fa-circle-o';

        };


    c.getStatusClass =
        function(
            status
        ) {

            var value =
                lower(
                    status
                );


            if (
                value === 'published'
            ) {

                return 'status-published';

            }


            if (
                value === 'draft'
            ) {

                return 'status-draft';

            }


            return 'status-other';

        };


    c.getTrackingClass =
        function(
            status
        ) {

            var value =
                lower(
                    status
                );


            if (
                value === 'applied' ||
                value === 'selected' ||
                value === 'scheduled' ||
                value === 'completed' ||
                value === 'passed' ||
                value.indexOf('offer') !== -1 ||
                value.indexOf('placed') !== -1 ||
                value.indexOf('accepted') !== -1
            ) {

                return 'tracking-positive';

            }


            if (
                value === 'pending' ||
                value.indexOf('pending') !== -1 ||
                value.indexOf('await') !== -1
            ) {

                return 'tracking-warning';

            }


            if (
                value === 'failed' ||
                value.indexOf('reject') !== -1 ||
                value.indexOf('withdraw') !== -1
            ) {

                return 'tracking-negative';

            }


            return 'tracking-neutral';

        };


    c.isInterviewActivity =
        function(
            value
        ) {

            var text =
                lower(
                    value
                );


            return (
                !!text &&
                text !== '—' &&
                text !== 'none' &&
                text !== 'not scheduled' &&
                text !== 'not applicable'
            );

        };


    c.isOfferActivity =
        function(
            value
        ) {

            var text =
                lower(
                    value
                );


            return (
                text.indexOf(
                    'offer'
                ) !== -1
            ) ||
            (
                text.indexOf(
                    'placed'
                ) !== -1
            ) ||
            (
                text.indexOf(
                    'accepted'
                ) !== -1
            );

        };


    /* =====================================================
       FILTER CHANGE
       ===================================================== */

    c.filtersChanged =
        function() {

            c.currentPage = 1;

            c.studentPage = 1;


            c.updateCompanyName();

            c.rebuildView();

            c.rebuildAnalytics();

            c.rebuildStudentFilterChoices();

            c.rebuildStudentView();

        };


    c.clearSearch =
        function() {

            c.filters.search = '';

            c.filtersChanged();

        };


    c.resetFilters =
        function() {

            c.filters = {

                search: '',

                company: 'all',

                result: 'all',

                type: 'all',

                status: 'all'

            };


            c.studentFilters = {

                search: '',

                application: 'all',

                interview: 'all',

                offer: 'all',

                assessment: 'all'

            };


            c.currentPage = 1;

            c.studentPage = 1;

            c.analyticsOpen = false;

            c.studentsOpen = false;

            c.selectedAssessment = null;

            c.studentDetail = null;

            c.updateCompanyName();

            c.rebuildView();

            c.rebuildAnalytics();

            c.rebuildStudentFilterChoices();

            c.rebuildStudentView();

        };


    /* =====================================================
       ASSESSMENT DETAIL
       ===================================================== */

    c.openDetails =
        function(
            row
        ) {

            c.analyticsOpen = false;

            c.studentsOpen = false;

            c.studentDetail = null;

            c.selectedAssessment =
                angular.copy(
                    row
                );

        };


    c.closeDetails =
        function() {

            c.selectedAssessment = null;

        };


    /* =====================================================
       STUDENT DETAIL
       ===================================================== */

    c.openStudentDetail =
        function(
            row
        ) {

            var detail =
                angular.copy(
                    row
                );


            detail.assessments = [];


            var rows =
                c.data.rows ||
                [];


            var i;


            for (
                i = 0;
                i < rows.length;
                i++
            ) {

                var assessment =
                    rows[i];


                var sameStudent =
                    (
                        row.student_sys_id &&
                        assessment.student &&
                        String(
                            row.student_sys_id
                        ) ===
                        String(
                            assessment.student
                        )
                    ) ||
                    (
                        row.student_id &&
                        assessment.student_id &&
                        String(
                            row.student_id
                        ) ===
                        String(
                            assessment.student_id
                        )
                    );


                if (
                    !sameStudent
                ) {

                    continue;

                }


                if (
                    c.filters.company !==
                    'all' &&
                    lower(
                        assessment.company_id
                    ) !==
                    lower(
                        c.filters.company
                    )
                ) {

                    continue;

                }


                detail.assessments.push(
                    assessment
                );

            }


            c.analyticsOpen = false;

            c.studentsOpen = false;

            c.selectedAssessment = null;

            c.studentDetail =
                detail;

        };


    c.openStudentFromAssessment =
        function(
            row
        ) {

            var students =
                c.data.studentRows ||
                [];


            var i;


            for (
                i = 0;
                i < students.length;
                i++
            ) {

                if (
                    row.student &&
                    String(
                        students[i]
                            .student_sys_id
                    ) ===
                    String(
                        row.student
                    )
                ) {

                    c.openStudentDetail(
                        students[i]
                    );

                    return;

                }

            }


            c.openStudentDetail({

                student_sys_id:
                    row.student,

                student_name:
                    row.student_name,

                student_id:
                    row.student_id,

                initials:
                    row.student_initials,

                company_name:
                    row.company_name,

                opportunity:
                    row.opportunity,

                assessment_result:
                    row.result,

                application_status:
                    '—',

                interview_status:
                    '—',

                offer_status:
                    '—'

            });

        };


    c.closeStudentDetail =
        function() {

            c.studentDetail = null;

        };


    c.closeStudentDetailOnBackdrop =
        function(
            event
        ) {

            if (
                event &&
                event.target ===
                event.currentTarget
            ) {

                c.closeStudentDetail();

            }

        };


    /* =====================================================
       EDIT
       ===================================================== */

    c.openAssessmentById =
        function(
            sysId,
            edit
        ) {

            var rows =
                c.data.rows ||
                [];


            var i;


            for (
                i = 0;
                i < rows.length;
                i++
            ) {

                if (
                    String(
                        rows[i].sys_id
                    ) ===
                    String(
                        sysId
                    )
                ) {

                    if (
                        edit
                    ) {

                        c.openEditAssessment(
                            rows[i]
                        );

                    } else {

                        c.openDetails(
                            rows[i]
                        );

                    }


                    return;

                }

            }

        };


    c.openEditAssessment =
        function(
            row
        ) {

            c.analyticsOpen = false;

            c.studentsOpen = false;

            c.selectedAssessment = null;

            c.studentDetail = null;


            c.form = {

                sys_id:
                    row.sys_id,

                assessment_date:
                    row.assessment_date_raw ||
                    '',

                assessment_id:
                    row.assessment_id ||
                    '',

                assessment_name:
                    row.assessment_name ||
                    '',

                assessment_type:
                    row.assessment_type_value ||
                    '',

                maximum_score:
                    row.maximum_score,

                student:
                    row.student ||
                    '',

                opportunity:
                    row.opportunity_value ||
                    '',

                result:
                    row.result_value ||
                    '',

                score:
                    row.score,

                duration:
                    row.duration ||
                    '',

                status:
                    row.status_value ||
                    '',

                remarks:
                    row.remarks ||
                    ''

            };


            c.formError = '';

            c.formOpen = true;

        };


    c.closeForm =
        function() {

            if (
                c.saving
            ) {

                return;

            }


            c.formOpen = false;

            c.formError = '';

        };


    c.closeFormOnBackdrop =
        function(
            event
        ) {

            if (
                event &&
                event.target ===
                event.currentTarget
            ) {

                c.closeForm();

            }

        };


    c.saveAssessment =
        function() {

            c.formError = '';


            if (
                !c.form ||
                !c.form.sys_id
            ) {

                c.formError =
                    'Only existing assessments can be edited.';

                return;

            }


            var maximum =
                Number(
                    c.form.maximum_score
                );


            var score =
                Number(
                    c.form.score
                );


            if (
                !isNaN(maximum) &&
                !isNaN(score) &&
                score > maximum
            ) {

                c.formError =
                    'Score cannot be greater than maximum score.';

                return;

            }


            c.saving = true;


            c.server.get({

                action:
                    'edit',

                form:
                    c.form

            })
            .then(
                function(
                    response
                ) {

                    c.saving = false;

                    c.data =
                        response.data;


                    if (
                        c.data.error
                    ) {

                        c.formError =
                            c.data.error;

                        return;

                    }


                    c.formOpen = false;

                    c.selectedAssessment = null;

                    c.studentDetail = null;


                    c.updateCompanyName();

                    c.rebuildView();

                    c.rebuildAnalytics();

                    c.rebuildStudentFilterChoices();

                    c.rebuildStudentView();

                },
                function() {

                    c.saving = false;

                    c.formError =
                        'Unable to save the assessment.';

                }
            );

        };


    /* =====================================================
       REFRESH
       ===================================================== */

    c.refresh =
        function() {

            if (
                c.loading
            ) {

                return;

            }


            c.loading = true;


            c.server.get({

                action:
                    'refresh'

            })
            .then(
                function(
                    response
                ) {

                    c.loading = false;

                    c.data =
                        response.data;


                    c.updateCompanyName();

                    c.rebuildView();

                    c.rebuildAnalytics();

                    c.rebuildStudentFilterChoices();

                    c.rebuildStudentView();

                },
                function() {

                    c.loading = false;

                    c.data.error =
                        'Unable to refresh assessment data.';

                }
            );

        };


    /* =====================================================
       INITIALIZE
       ===================================================== */

    c.updateCompanyName();

    c.rebuildView();

    c.rebuildAnalytics();

    c.rebuildStudentFilterChoices();

    c.rebuildStudentView();


    c.goTo = function(pageId) {
        if (!pageId) return;
        var map = {
            'dashboard': 'campus360_tpo_home',
            'home': 'campus360_tpo_home',
            'campus360_tpo_home': 'campus360_tpo_home',
            'students': 'campus360_tpo_student_management',
            'student_management': 'campus360_tpo_student_management',
            'campus360_tpo_student_management': 'campus360_tpo_student_management',
            'skills': 'campus360_tpo_skill_intelligence_new',
            'skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence_new': 'campus360_tpo_skill_intelligence_new',
            'assessments': 'student_assessments_new',
            'student_assessments': 'student_assessments_new',
            'student_assessments_new': 'student_assessments_new',
            'companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies_new': 'campus360_tpo_companies_new',
            'opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities_new': 'campus360_tpo_opportunities_new',
            'applications': 'campus360_tpo_application_new',
            'application': 'campus360_tpo_application_new',
            'campus360_tpo_application': 'campus360_tpo_application_new',
            'campus360_tpo_application_new': 'campus360_tpo_application_new',
            'interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews_new': 'campus360_tpo_interviews_new',
            'outcomes': 'campus360_tpo_placement_outcomes',
            'placement_outcomes': 'campus360_tpo_placement_outcomes',
            'campus360_tpo_placement_outcomes': 'campus360_tpo_placement_outcomes',
            'training': 'campus360_tpo_training_programs',
            'training_programs': 'campus360_tpo_training_programs',
            'campus360_tpo_training_programs': 'campus360_tpo_training_programs',
            'enrollments': 'campus360_tpo_training_programs',
            'campus360_tpo_enrollments': 'campus360_tpo_training_programs',
            'mock_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_mock_interviews': 'campus360_tpo_interviews_new',
            'risk': 'campus360_tpo_student_management',
            'campus360_tpo_risk_intelligence': 'campus360_tpo_student_management',
            'interventions': 'campus360_tpo_student_management',
            'campus360_tpo_interventions': 'campus360_tpo_student_management',
            'readiness': 'campus360_tpo_skill_intelligence_new',
            'ai_assistant': 'campus360_tpo_ai_assistant',
            'campus360_tpo_ai_assistant': 'campus360_tpo_ai_assistant'
        };
        var target = map[pageId] || pageId;
        if (typeof $window !== 'undefined' && $window.location) {
            $window.location.href = '?id=' + encodeURIComponent(target);
        } else {
            window.location.href = '?id=' + encodeURIComponent(target);
        }
    };
    c.goToPage = function(pageId) { c.goTo(pageId); };
    c.navigate = function(pageId) { c.goTo(pageId); };

};

