/* =========================================================
   CAMPUS360 TPO — STUDENT ASSESSMENTS
   COMPLETE UPDATED CSS
   ========================================================= */


/* =========================================================
   GLOBAL RESET / FULL PAGE
   ========================================================= */

html,
body {
  width:100% !important;
  height:100% !important;
  min-width:100% !important;
  min-height:100% !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
  background:#f5f7fb !important;
}

body:has(.campus360-tpo-assessments) {
  overflow:hidden !important;
  background:#f5f7fb !important;
}


/* Hide native ServiceNow chrome on this page */

body:has(.campus360-tpo-assessments) #sp-header,
body:has(.campus360-tpo-assessments) .sp-header,
body:has(.campus360-tpo-assessments) .sp-navbar,
