body:has(.campus360-tpo-assessments) nav.navbar,
body:has(.campus360-tpo-assessments) .navbar.sp-navbar,
body:has(.campus360-tpo-assessments) .navbar.navbar-default,
body:has(.campus360-tpo-assessments) .navbar.navbar-inverse {
  display:none !important;
  visibility:hidden !important;
  height:0 !important;
  min-height:0 !important;
  max-height:0 !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
}


/* Remove ServiceNow wrappers */

body:has(.campus360-tpo-assessments) .page,
body:has(.campus360-tpo-assessments) #sp-page,
body:has(.campus360-tpo-assessments) #sp-main,
body:has(.campus360-tpo-assessments) .sp-page,
body:has(.campus360-tpo-assessments) .sp-main,
body:has(.campus360-tpo-assessments) .page-wrapper,
body:has(.campus360-tpo-assessments) .main-content,
body:has(.campus360-tpo-assessments) .container,
body:has(.campus360-tpo-assessments) .container-fluid,
body:has(.campus360-tpo-assessments) .row {
  width:100% !important;
  max-width:none !important;
  margin:0 !important;
  padding:0 !important;
  border:0 !important;
}

body:has(.campus360-tpo-assessments) [class*="col-"] {
  width:100% !important;
  max-width:none !important;
  margin:0 !important;
  padding:0 !important;
}


/* =========================================================
   APPLICATION SHELL
   ========================================================= */

.campus360-tpo-assessments,
.campus360-tpo-assessments *,
.campus360-tpo-assessments *::before,
.campus360-tpo-assessments *::after {
  box-sizing:border-box !important;
}

.campus360-tpo-assessments {
  position:fixed !important;
  inset:0 !important;

  width:100vw !important;
  height:100vh !important;

  min-width:100vw !important;
  min-height:100vh !important;

  max-width:100vw !important;
  max-height:100vh !important;

  margin:0 !important;
  padding:0 !important;

  display:flex !important;

  overflow:hidden !important;

  background:
    linear-gradient(
      135deg,
      #f4f7fb 0%,
      #fbfaff 56%,
      #f3f8fb 100%
    ) !important;

  color:#23364b !important;

  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif !important;

  z-index:999999 !important;
}

.campus360-tpo-assessments button,
.campus360-tpo-assessments input,
.campus360-tpo-assessments select,
.campus360-tpo-assessments textarea {
  font-family:inherit !important;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.tpo-sidebar {
  width:242px !important;
  min-width:242px !important;
  max-width:242px !important;

  height:100vh !important;

  flex:0 0 242px !important;

  display:flex !important;
  flex-direction:column !important;

  position:relative !important;

  overflow:hidden !important;

  background:
    linear-gradient(
      180deg,
      #10092a 0%,
      #130d31 55%,
      #0d0822 100%
    ) !important;

  border-right:1px solid #2b2247 !important;

  color:#fff !important;

  z-index:20 !important;
}


/* =========================================================
   BRAND
   ========================================================= */

.tpo-brand {
  height:84px !important;
  min-height:84px !important;

  padding:0 18px !important;

  display:flex !important;
  align-items:center !important;

  gap:13px !important;

  border-bottom:1px solid rgba(255,255,255,.08) !important;
}

.tpo-brand-logo {
  width:46px !important;
  height:46px !important;

  min-width:46px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:13px !important;

  background:
    linear-gradient(
      135deg,
      #723fff,
      #8c4cf2
    ) !important;

  color:#fff !important;

  font-size:22px !important;
  font-weight:950 !important;

  box-shadow:
    0 9px 22px rgba(106,57,235,.27) !important;
}

.tpo-brand-text {
  min-width:0 !important;

  display:flex !important;
  flex-direction:column !important;
}

.tpo-brand-text strong {
  color:#fff !important;

  font-size:18px !important;
  font-weight:900 !important;

  line-height:1.1 !important;
}

.tpo-brand-text span {
  margin-top:4px !important;

  color:#bcaeff !important;

  font-size:9px !important;
  font-weight:850 !important;

  letter-spacing:.8px !important;
}


/* =========================================================
   PROFILE
   ========================================================= */

.tpo-profile-card {
  margin:17px 12px 10px !important;

  min-height:72px !important;

  padding:11px !important;

  display:flex !important;
  align-items:center !important;

  gap:10px !important;

  border:1px solid #35285b !important;

  border-radius:15px !important;

  background:
    linear-gradient(
      145deg,
      #1c1340,
      #21174a
    ) !important;
}

.tpo-profile-avatar {
  width:43px !important;
  height:43px !important;

  min-width:43px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:50% !important;

  background:
    linear-gradient(
      135deg,
      #7540f4,
      #944ff5
    ) !important;

  color:#fff !important;

  font-size:10px !important;
  font-weight:950 !important;
}

.tpo-profile-info {
  min-width:0 !important;

  display:flex !important;
  flex-direction:column !important;
}

.tpo-profile-info strong {
  color:#fff !important;

  font-size:12px !important;
  font-weight:850 !important;

  line-height:1.2 !important;
}

.tpo-profile-info span {
  margin-top:4px !important;

  color:#aa9fc5 !important;

  font-size:8px !important;
}


/* =========================================================
   NAV
   ========================================================= */

.tpo-sidebar-nav {
  flex:1 !important;
  min-height:0 !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  padding:3px 10px 10px !important;

  scrollbar-width:thin !important;
  scrollbar-color:#4b3975 transparent !important;
}

.tpo-sidebar-nav::-webkit-scrollbar {
  width:5px !important;
}

.tpo-sidebar-nav::-webkit-scrollbar-track {
  background:transparent !important;
}

.tpo-sidebar-nav::-webkit-scrollbar-thumb {
  background:#4b3975 !important;
  border-radius:10px !important;
}

.tpo-nav-label {
  padding:15px 12px 7px !important;

  color:#83769d !important;

  font-size:8px !important;
  font-weight:900 !important;

  letter-spacing:1.4px !important;
}

.tpo-nav-item {
  width:100% !important;

  min-height:42px !important;

  margin:2px 0 !important;

  padding:0 12px !important;

  display:flex !important;
  align-items:center !important;

  gap:11px !important;

  border:0 !important;

  border-radius:10px !important;

  background:transparent !important;

  color:#e6e0f1 !important;

  font-size:12px !important;
  font-weight:750 !important;

  text-align:left !important;

  cursor:pointer !important;

  transition:
    background .16s ease,
    color .16s ease !important;
}

.tpo-nav-item:hover {
  background:#211743 !important;
  color:#fff !important;
}

.tpo-nav-item.active {
  background:
    linear-gradient(
      135deg,
      #793bef,
      #8b48f2
    ) !important;

  color:#fff !important;

  box-shadow:
    0 8px 18px rgba(103,50,224,.27) !important;
}

.tpo-nav-icon {
  width:21px !important;
  height:21px !important;

  min-width:21px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  font-size:13px !important;
}

.tpo-nav-count {
  margin-left:auto !important;

  min-width:22px !important;
  height:21px !important;

  padding:0 6px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:999px !important;

  background:rgba(255,255,255,.18) !important;

  color:#fff !important;

  font-size:9px !important;
  font-weight:950 !important;
}


/* =========================================================
