  align-items:center !important;

  gap:7px !important;

  color:#b8acd0 !important;

  font-size:8px !important;
  font-weight:850 !important;
}

.tpo-footer-status span {
  width:7px !important;
  height:7px !important;

  border-radius:50% !important;

  background:#33d29a !important;
}

