  display:block !important;

  margin-top:5px !important;

  color:#75698d !important;

  font-size:7px !important;
}


/* =========================================================
   MAIN
   ========================================================= */

.tpo-main {
  flex:1 1 auto !important;

  width:calc(100vw - 242px) !important;
  max-width:calc(100vw - 242px) !important;

  min-width:0 !important;

  height:100vh !important;

  position:relative !important;

  overflow:hidden !important;
}


/* =========================================================
   TOPBAR
   ========================================================= */

.tpo-topbar {
  width:100% !important;

  height:74px !important;
  min-height:74px !important;

  padding:0 22px !important;

  display:flex !important;

  align-items:center !important;
  justify-content:space-between !important;

  background:#fff !important;

  border-bottom:1px solid #dde4eb !important;

  position:relative !important;

  z-index:10 !important;
}

.tpo-topbar-left,
.tpo-topbar-right {
  display:flex !important;
  align-items:center !important;
}

.tpo-topbar-right {
  gap:8px !important;
}

.tpo-menu-button {
  width:42px !important;
  height:42px !important;

  padding:0 !important;

  display:flex !important;
  flex-direction:column !important;

  align-items:center !important;
  justify-content:center !important;

  gap:5px !important;

  border:1px solid #dbe3eb !important;

  border-radius:10px !important;

  background:#fff !important;

  cursor:pointer !important;
}

.tpo-menu-button span {
  width:19px !important;
  height:2px !important;

  display:block !important;

  border-radius:2px !important;

  background:#6d3fe0 !important;
}


/* Breadcrumb styled like reference */

.tpo-breadcrumb {
  margin-left:16px !important;

  min-width:250px !important;

  height:49px !important;

  padding:0 15px !important;

  display:flex !important;
  flex-direction:column !important;

  justify-content:center !important;

  border-radius:10px !important;

  background:#f7f7f8 !important;
}

.tpo-breadcrumb span {
  color:#7040df !important;

  font-size:8px !important;
  font-weight:950 !important;

  letter-spacing:1.2px !important;
}

.tpo-breadcrumb b {
  display:none !important;
}

.tpo-breadcrumb strong {
  margin-top:2px !important;

  color:#23364c !important;

  font-size:16px !important;
  font-weight:900 !important;
}


/* Topbar icons */

.tpo-top-icon {
  width:40px !important;
  height:40px !important;

  padding:0 !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  position:relative !important;

  border:1px solid #dde4eb !important;

  border-radius:50% !important;

  background:#fff !important;

  color:#6f7f8f !important;

  cursor:pointer !important;
}

.tpo-top-icon:hover {
  background:#f7f3ff !important;

  color:#7040df !important;

  border-color:#d5c7f0 !important;
}

.tpo-notification-dot {
  position:absolute !important;

  top:6px !important;
  right:6px !important;

  width:7px !important;
  height:7px !important;

  border-radius:50% !important;

  background:#ef4a4a !important;

  border:2px solid #fff !important;
}

.tpo-top-profile {
  display:flex !important;
  align-items:center !important;

  gap:9px !important;

  margin-left:5px !important;
}

.tpo-top-avatar {
  width:39px !important;
  height:39px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:50% !important;

  background:
    linear-gradient(
      135deg,
      #7140df,
      #8a4bed
    ) !important;

  color:#fff !important;

  font-size:9px !important;
  font-weight:950 !important;
}

.tpo-top-profile-info {
  display:flex !important;
  flex-direction:column !important;
}

.tpo-top-profile-info strong {
  color:#273a50 !important;

  font-size:11px !important;
  font-weight:900 !important;
}

.tpo-top-profile-info span {
  margin-top:2px !important;

  color:#909ca8 !important;

  font-size:8px !important;
}

.tpo-top-chevron {
  color:#7a8896 !important;

  font-size:13px !important;
}


/* =========================================================
   CONTENT
   ========================================================= */

.tpo-content {
  width:100% !important;

  height:calc(100vh - 74px) !important;

  min-height:0 !important;

  padding:14px 18px 30px !important;

  display:flex !important;

  flex-direction:column !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  scrollbar-width:thin !important;
  scrollbar-color:#bfc7d0 #f4f6f8 !important;
}

.tpo-content::-webkit-scrollbar {
  width:9px !important;
}

.tpo-content::-webkit-scrollbar-track {
  background:#f2f4f7 !important;
}

.tpo-content::-webkit-scrollbar-thumb {
  background:#c1c8d0 !important;
  border-radius:10px !important;
}

.tpo-content::-webkit-scrollbar-thumb:hover {
  background:#aeb7c1 !important;
}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.tpo-page-header {
  flex:0 0 91px !important;

  min-height:91px !important;

  padding:15px 18px !important;

  display:flex !important;

  align-items:center !important;
  justify-content:space-between !important;

  gap:15px !important;

  border:1px solid #dce5ef !important;

  border-radius:13px !important;

  background:
    linear-gradient(
      110deg,
      #edf4ff,
      #f6efff
    ) !important;

  box-shadow:
    0 3px 12px rgba(30,44,64,.03) !important;
}

.page-title-block {
  min-width:0 !important;
}

.tpo-eyebrow {
  margin-bottom:5px !important;

  color:#6b41d8 !important;

  font-size:8px !important;
  font-weight:950 !important;

  letter-spacing:1.4px !important;
}

.tpo-page-header h1 {
  margin:0 !important;

  color:#14283f !important;

  font-size:26px !important;
  font-weight:950 !important;

  line-height:1.1 !important;
}

.tpo-page-header p {
  margin:5px 0 0 !important;

  color:#65788d !important;

  font-size:9px !important;

  line-height:1.4 !important;

  font-weight:600 !important;
}

.page-header-actions {
  display:flex !important;

  align-items:center !important;

  justify-content:flex-end !important;

  gap:6px !important;

  flex-wrap:wrap !important;
}

.header-action {
  height:35px !important;

  padding:0 10px !important;

  display:inline-flex !important;

  align-items:center !important;
  justify-content:center !important;

  gap:5px !important;

  border:1px solid #d7dfe7 !important;

  border-radius:8px !important;

  background:#fff !important;

  color:#647689 !important;

  font-size:8px !important;
  font-weight:900 !important;

  cursor:pointer !important;
}

.header-action:hover {
  background:#f8f5ff !important;

  border-color:#d4c6ef !important;

  color:#7040df !important;
}

.header-action.analytics {
  color:#7040df !important;
}

.header-action.students {
  color:#2875bb !important;
}


/* =========================================================
   KPI
   ========================================================= */

.tpo-kpi-grid {
  flex:0 0 80px !important;

  min-height:80px !important;

  margin-top:9px !important;

  display:grid !important;

  grid-template-columns:
    repeat(5,minmax(0,1fr)) !important;

  gap:8px !important;
}

.tpo-kpi-card {
  min-height:80px !important;

  padding:10px !important;

  display:flex !important;

  align-items:center !important;

  gap:9px !important;

  border:1px solid transparent !important;

  border-radius:10px !important;
}

.tpo-kpi-card.purple {
  background:#e8ddff !important;
  border-color:#d4c3f5 !important;
}

.tpo-kpi-card.green {
  background:#e0f5e9 !important;
  border-color:#bee4ce !important;
}

.tpo-kpi-card.red {
  background:#ffe7e7 !important;
  border-color:#ffd0d0 !important;
}

.tpo-kpi-card.blue {
  background:#e3efff !important;
  border-color:#c6dbf5 !important;
}

.tpo-kpi-card.orange {
  background:#fff0d9 !important;
  border-color:#eed7ad !important;
}

.tpo-kpi-icon {
  width:36px !important;
  height:36px !important;

  min-width:36px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:9px !important;

  background:rgba(255,255,255,.9) !important;

  font-size:15px !important;
}

.tpo-kpi-card.purple .tpo-kpi-icon {
  color:#7040ef !important;
}

.tpo-kpi-card.green .tpo-kpi-icon {
  color:#168052 !important;
}

.tpo-kpi-card.red .tpo-kpi-icon {
  color:#dc4848 !important;
}

.tpo-kpi-card.blue .tpo-kpi-icon {
  color:#2e73c7 !important;
}

.tpo-kpi-card.orange .tpo-kpi-icon {
  color:#c9790f !important;
}

.tpo-kpi-card > div:last-child {
  min-width:0 !important;

  display:flex !important;
  flex-direction:column !important;
}

.tpo-kpi-card span {
  color:#718194 !important;

  font-size:6px !important;
  font-weight:950 !important;

  letter-spacing:.7px !important;
}

.tpo-kpi-card strong {
  margin-top:3px !important;

  color:#1a2c42 !important;

  font-size:21px !important;
  font-weight:950 !important;

  line-height:1 !important;
}

.tpo-kpi-card small {
  margin-top:4px !important;

  color:#8b98a5 !important;

  font-size:6px !important;
}


/* =========================================================
   FILTER
   ========================================================= */

.tpo-filter-card {
  flex:0 0 58px !important;

  min-height:58px !important;

  margin-top:8px !important;

  padding:7px !important;

  display:flex !important;

  align-items:center !important;

  gap:7px !important;

  border:1px solid #dce4eb !important;

  border-radius:10px !important;

  background:#fff !important;
}

.search-box {
  flex:1 1 auto !important;

  min-width:220px !important;

  height:36px !important;

  padding:0 9px !important;

  display:flex !important;

  align-items:center !important;

  gap:7px !important;

  border:1px solid #d5dee8 !important;

  border-radius:8px !important;

  background:#fff !important;

  color:#7040df !important;
}

.search-box input {
  flex:1 !important;

  min-width:0 !important;

  height:100% !important;

  padding:0 !important;

  border:0 !important;

  outline:0 !important;

  background:transparent !important;

  color:#4f6175 !important;

  font-size:8px !important;
}

.search-box input::placeholder {
  color:#9da7b1 !important;
}

.search-box button {
  width:22px !important;
  height:22px !important;

  padding:0 !important;

  border:0 !important;

  background:transparent !important;

  color:#97a2ad !important;

  cursor:pointer !important;
}

.filter-field {
  width:138px !important;

  flex:0 0 138px !important;

  display:flex !important;

  flex-direction:column !important;

  gap:2px !important;
}

.filter-field.company-field {
  width:160px !important;

  flex-basis:160px !important;
}

.filter-field label {
  color:#8996a3 !important;

  font-size:5px !important;

  font-weight:950 !important;

  letter-spacing:.7px !important;
}

.filter-field select {
  width:100% !important;

  height:36px !important;

  padding:0 8px !important;

  border:1px solid #d4dee7 !important;

  border-radius:8px !important;

  background:#fff !important;

  color:#586b7e !important;

  font-size:7px !important;

  outline:0 !important;
}

.filter-field select:focus,
.search-box:focus-within {
  border-color:#b29add !important;

  box-shadow:
    0 0 0 3px rgba(112,64,223,.07) !important;
}


/* =========================================================
   COMPANY SUMMARY
   IMPORTANT: SIX STATS + TWO BUTTONS
   NO WRAPPING / NO OVERLAP
   ========================================================= */

.company-strip {
  flex:0 0 62px !important;

  min-height:62px !important;

  margin-top:8px !important;

  padding:7px 9px !important;

  display:flex !important;

  align-items:center !important;

  gap:6px !important;

  overflow-x:auto !important;
  overflow-y:hidden !important;

  border:1px solid #dce4ea !important;

  border-radius:10px !important;

  background:#fff !important;

  scrollbar-width:thin !important;

  scrollbar-color:#cbd1d8 transparent !important;
}

.company-strip::-webkit-scrollbar {
  height:5px !important;
}

.company-strip::-webkit-scrollbar-track {
  background:transparent !important;
}

.company-strip::-webkit-scrollbar-thumb {
  background:#cbd1d8 !important;
  border-radius:10px !important;
}

.company-strip-title {
  flex:1 1 210px !important;

  min-width:210px !important;

  display:flex !important;

  align-items:center !important;

  gap:7px !important;
}

.company-strip-icon {
  width:31px !important;
  height:31px !important;

  min-width:31px !important;

  display:flex !important;

  align-items:center !important;
  justify-content:center !important;

  border-radius:8px !important;

  background:#efe9ff !important;

  color:#7040df !important;
}

.company-strip-title > div:last-child {
  min-width:0 !important;
}

.company-strip-title span {
  display:block !important;

  color:#939eaa !important;

  font-size:5px !important;

  font-weight:950 !important;

  letter-spacing:.7px !important;
}

.company-strip-title strong {
  display:block !important;

  max-width:180px !important;

  margin-top:2px !important;

  color:#33475b !important;

  font-size:8px !important;

  font-weight:950 !important;

  white-space:nowrap !important;

  overflow:hidden !important;

  text-overflow:ellipsis !important;
}


/* SIX statistics */

.company-strip-stat {
  flex:0 0 93px !important;

  width:93px !important;

  min-width:93px !important;

  padding:6px 7px !important;

  border:1px solid #e3e8ed !important;

  border-radius:7px !important;

  background:#fafbfd !important;
}

.company-strip-stat span {
  display:block !important;

  color:#929ca7 !important;

  font-size:4px !important;

  font-weight:950 !important;

  letter-spacing:.55px !important;
}

.company-strip-stat strong {
  display:block !important;

  margin-top:2px !important;

  color:#34485c !important;

  font-size:11px !important;

  font-weight:950 !important;
}


/* Two actions stay together */

.company-strip-actions {
  flex:0 0 auto !important;

  width:auto !important;

  min-width:63px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  gap:4px !important;
}

.company-strip-actions button {
  width:28px !important;
  height:28px !important;

  min-width:28px !important;

  padding:0 !important;

  display:flex !important;

  align-items:center !important;
  justify-content:center !important;

  border:1px solid #ddd4f0 !important;

  border-radius:7px !important;

  background:#fbfaff !important;

  color:#7040df !important;

  cursor:pointer !important;
}

.company-strip-actions button:hover {
  background:#f2edff !important;

  border-color:#cdbdeb !important;
}


/* =========================================================
   STATUS LINE
   ========================================================= */

.assessment-status-line {
  flex:0 0 30px !important;

  min-height:30px !important;

  margin-top:3px !important;

  padding:0 4px !important;

  display:flex !important;

  align-items:center !important;

  gap:14px !important;

  color:#7d8b99 !important;

  font-size:6px !important;
}

.assessment-status-line > div {
  display:flex !important;

  align-items:center !important;

  gap:4px !important;
}

.assessment-status-line strong {
  color:#405367 !important;

  font-size:7px !important;
}

.status-dot {
  width:7px !important;
  height:7px !important;

  min-width:7px !important;

  border-radius:50% !important;
}

.status-dot.passed {
  background:#1bab6e !important;
}

.status-dot.failed {
  background:#e65353 !important;
}

.status-dot.pending {
  background:#e3a21b !important;
}

.status-line-spacer {
  flex:1 !important;
}

.assessment-status-line > span:last-child {
  color:#99a4ae !important;

  font-size:6px !important;
}


/* =========================================================
   ASSESSMENT TABLE CARD
   TALLER TO MAKE RECORDS EASIER TO SCROLL
   ========================================================= */

.tpo-table-card {
  flex:0 0 455px !important;

  height:455px !important;

  min-height:455px !important;

  margin-top:0 !important;

  display:flex !important;

  flex-direction:column !important;

  overflow:hidden !important;

  border:1px solid #dfe5eb !important;

  border-radius:11px !important;

  background:#fff !important;

  box-shadow:
    0 3px 12px rgba(29,43,61,.03) !important;
}


/* =========================================================
   TABLE HEADER
   ========================================================= */

.table-header {
  flex:0 0 55px !important;

  min-height:55px !important;

  padding:0 13px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  border-bottom:1px solid #e8edf1 !important;

  background:#fff !important;
}

.table-heading {
  min-width:0 !important;
}

.table-heading-title {
  display:flex !important;

  align-items:baseline !important;

  gap:7px !important;
}

.table-heading-title > span {
  color:#7040df !important;

  font-size:6px !important;

  font-weight:950 !important;

  letter-spacing:.8px !important;
}

.table-heading strong {
  color:#293e54 !important;

  font-size:12px !important;

  font-weight:950 !important;
}

.table-heading small {
  color:#99a3ad !important;

  font-size:6px !important;
}

.table-header-note {
  color:#99a4ae !important;

  font-size:6px !important;

  white-space:nowrap !important;
}


/* =========================================================
   TABLE SCROLL
   ========================================================= */

.table-scroll-area {
  flex:1 1 auto !important;

  min-height:0 !important;

  overflow-x:auto !important;

  overflow-y:auto !important;

  scrollbar-width:thin !important;

  scrollbar-color:#c5ccd4 #fafbfd !important;
}

.table-scroll-area::-webkit-scrollbar {
  width:8px !important;

  height:8px !important;
}

.table-scroll-area::-webkit-scrollbar-track {
  background:#f7f8fa !important;
}

.table-scroll-area::-webkit-scrollbar-thumb {
  background:#c5ccd4 !important;

  border-radius:10px !important;
}

.assessment-table {
  width:100% !important;

  min-width:1240px !important;

  border-collapse:collapse !important;

  background:#fff !important;
}

.assessment-table thead {
  position:sticky !important;

  top:0 !important;

  z-index:5 !important;

  background:#f7f9fb !important;
}

.assessment-table th {
  height:38px !important;

  padding:0 9px !important;

  color:#788696 !important;

  font-size:6px !important;

  font-weight:950 !important;

  letter-spacing:.3px !important;

  text-transform:uppercase !important;

  text-align:left !important;

  white-space:nowrap !important;

  border-bottom:1px solid #dfe6ec !important;
}

.assessment-table td {
  height:55px !important;

  padding:7px 9px !important;

  color:#536678 !important;

  font-size:7px !important;

  vertical-align:middle !important;

  border-bottom:1px solid #edf1f4 !important;
}

.assessment-table tbody tr:hover {
  background:#fbfaff !important;
}


/* =========================================================
   TABLE CELLS
   ========================================================= */

.id-link {
  padding:0 !important;

  border:0 !important;

  background:transparent !important;

  color:#1466b0 !important;

  font-size:7px !important;

  font-weight:950 !important;

  cursor:pointer !important;
}

.id-link:hover {
  text-decoration:underline !important;
}

.date-cell {
  color:#647689 !important;

  white-space:nowrap !important;
}

.assessment-cell {
  min-width:180px !important;

  max-width:220px !important;
}

.assessment-cell strong {
  display:block !important;

  color:#31465b !important;

  font-size:8px !important;

  font-weight:900 !important;

  white-space:nowrap !important;

  overflow:hidden !important;

  text-overflow:ellipsis !important;
}

.assessment-cell small {
  display:block !important;

  max-width:210px !important;

  margin-top:3px !important;

  color:#98a3ad !important;

  font-size:6px !important;

  white-space:nowrap !important;

  overflow:hidden !important;

  text-overflow:ellipsis !important;
}

.company-name-cell {
  color:#32485d !important;

  font-size:7px !important;

  font-weight:900 !important;
}

.opportunity-cell {
  color:#617286 !important;

  font-size:7px !important;
}


/* =========================================================
   TAGS
   ========================================================= */

.type-tag,
.result-tag,
.status-tag {
  display:inline-flex !important;

  align-items:center !important;

  gap:4px !important;

  min-height:22px !important;

  padding:0 7px !important;

  border-radius:999px !important;

  font-size:6px !important;

  font-weight:900 !important;

  white-space:nowrap !important;
}

.type-tag {
  background:#f1edff !important;

  color:#7452cf !important;
}

.result-tag {
  background:#edf8f2 !important;

  color:#188052 !important;
}

.status-tag {
  background:#eef3f8 !important;

  color:#5c7186 !important;
}


/* =========================================================
   SCORE
   ========================================================= */

.score-cell {
  min-width:72px !important;
}

.score-cell strong {
  color:#30465c !important;

  font-size:8px !important;

  font-weight:950 !important;
}

.mini-score-bar {
  width:65px !important;

  height:5px !important;

  margin-top:4px !important;

  overflow:hidden !important;

  border-radius:999px !important;

  background:#e9edf2 !important;
}

.mini-score-bar span {
  display:block !important;

  height:100% !important;

  border-radius:999px !important;

  background:
    linear-gradient(
      90deg,
      #7040df,
      #9158f2
    ) !important;
}


/* =========================================================
   STUDENT
   ========================================================= */

.student-table-link {
  padding:0 !important;

  display:inline-flex !important;

  align-items:center !important;

  gap:7px !important;

  border:0 !important;

  background:transparent !important;

  text-align:left !important;

  cursor:pointer !important;
}

.table-student-avatar {
  width:30px !important;

  height:30px !important;

  min-width:30px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border-radius:50% !important;

  background:#eee8ff !important;

  color:#7040df !important;

  font-size:7px !important;

  font-weight:950 !important;
}

.student-table-text {
  min-width:0 !important;

  display:flex !important;

  flex-direction:column !important;
}

.student-table-text strong {
  color:#33485d !important;

  font-size:7px !important;

  font-weight:900 !important;

  white-space:nowrap !important;
}

.student-table-text small {
  margin-top:2px !important;

  color:#98a3ad !important;

  font-size:6px !important;
}


/* =========================================================
   TABLE ACTIONS
   ========================================================= */

.table-actions {
  display:flex !important;

  align-items:center !important;

  gap:5px !important;
}

.icon-action {
  width:29px !important;

  height:29px !important;

  padding:0 !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border:1px solid #dce4eb !important;

  border-radius:7px !important;

  background:#fff !important;

  color:#697b8d !important;

  cursor:pointer !important;
}

.icon-action:hover {
  background:#f7f3ff !important;

  border-color:#d7c9ee !important;

  color:#7040df !important;
}


/* =========================================================
   EMPTY TABLE
   ========================================================= */

.no-records {
  min-height:240px !important;

  display:flex !important;

  flex-direction:column !important;

  align-items:center !important;

  justify-content:center !important;

  gap:7px !important;

  color:#8f9ba6 !important;
}

.empty-table-icon {
  width:43px !important;

  height:43px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border-radius:11px !important;

  background:#f1edff !important;

  color:#744bd2 !important;

  font-size:17px !important;
}

