  color:#506276 !important;

  font-size:10px !important;
}

.no-records span {
  font-size:7px !important;
}


/* =========================================================
   TABLE FOOTER
   ========================================================= */

.table-footer {
  flex:0 0 43px !important;

  min-height:43px !important;

  padding:0 12px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  border-top:1px solid #e7ecf1 !important;

  background:#fff !important;

  color:#8e9aa5 !important;

  font-size:7px !important;
}

.table-footer strong {
  color:#4c6074 !important;
}

.pagination-buttons {
  display:flex !important;

  gap:4px !important;
}

.pagination-buttons button {
  width:29px !important;

  height:27px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border:1px solid #dce4eb !important;

  border-radius:6px !important;

  background:#fff !important;

  color:#657789 !important;

  cursor:pointer !important;
}

.pagination-buttons button.active {
  background:#7040df !important;

  border-color:#7040df !important;

  color:#fff !important;
}

.pagination-buttons button:disabled {
  opacity:.4 !important;

  cursor:default !important;
}


/* =========================================================
   PAGE FOOTER
   ========================================================= */

.tpo-page-footer {
  flex:0 0 24px !important;

  min-height:24px !important;

  padding:0 3px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  color:#98a4ae !important;

  font-size:6px !important;
}


/* =========================================================
   DRAWERS
   ========================================================= */

.drawer-backdrop {
  position:fixed !important;

  inset:0 !important;

  background:rgba(14,10,29,.38) !important;

  backdrop-filter:blur(1px) !important;

  z-index:1000 !important;
}

.floating-drawer {
  position:fixed !important;

  top:0 !important;

  right:0 !important;

  bottom:0 !important;

  width:470px !important;

  max-width:90vw !important;

  height:100vh !important;

  display:flex !important;

  flex-direction:column !important;

  overflow:hidden !important;

  background:#fff !important;

  border-left:1px solid #dce4eb !important;

  box-shadow:
    -14px 0 36px rgba(16,25,38,.16) !important;

  z-index:1100 !important;

  transform:translateX(100%) !important;

  transition:
    transform .24s ease !important;
}

.floating-drawer.open {
  transform:translateX(0) !important;
}


/* Detail drawer */

.detail-drawer {
  transform:translateX(0) !important;
}


/* =========================================================
   DRAWER HEADER
   ========================================================= */

.drawer-header {
  flex:0 0 78px !important;

  min-height:78px !important;

  padding:14px 16px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  gap:12px !important;

  border-bottom:1px solid #e4e9ee !important;

  background:
    linear-gradient(
      110deg,
      #f5f1ff,
      #f7fbff
    ) !important;
}

.drawer-header > div {
  min-width:0 !important;
}

.drawer-header span {
  display:block !important;

  color:#7040df !important;

  font-size:6px !important;

  font-weight:950 !important;

  letter-spacing:1px !important;
}

.drawer-header h2 {
  margin:4px 0 0 !important;

  color:#26394e !important;

  font-size:16px !important;

  font-weight:950 !important;

  white-space:nowrap !important;

  overflow:hidden !important;

  text-overflow:ellipsis !important;
}

.drawer-header p {
  margin:3px 0 0 !important;

  color:#8e99a4 !important;

  font-size:7px !important;
}

.drawer-close {
  width:34px !important;

  height:34px !important;

  min-width:34px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border:1px solid #dce4eb !important;

  border-radius:8px !important;

  background:#fff !important;

  color:#6c7c8b !important;

  cursor:pointer !important;
}

.drawer-close:hover {
  background:#f7f3ff !important;

  border-color:#d7caef !important;

  color:#7040df !important;
}

.drawer-content {
  flex:1 !important;

  min-height:0 !important;

  padding:13px !important;

  overflow-y:auto !important;

  overflow-x:hidden !important;

  scrollbar-width:thin !important;

  scrollbar-color:#c6cdd5 transparent !important;
}

.drawer-content::-webkit-scrollbar {
  width:7px !important;
}

.drawer-content::-webkit-scrollbar-thumb {
  background:#c6cdd5 !important;

  border-radius:10px !important;
}


/* =========================================================
   ANALYTICS
   ========================================================= */

.drawer-metric-grid {
  display:grid !important;

  grid-template-columns:
    repeat(3,minmax(0,1fr)) !important;

  gap:6px !important;
}

.drawer-metric {
  padding:9px !important;

  border:1px solid #e0e6ec !important;

  border-radius:8px !important;

  background:#fafbfd !important;
}

.drawer-metric span {
  display:block !important;

  color:#8e99a4 !important;

  font-size:5px !important;

  font-weight:950 !important;

  letter-spacing:.7px !important;
}

.drawer-metric strong {
  display:block !important;

  margin-top:3px !important;

  color:#34495e !important;

  font-size:14px !important;

  font-weight:950 !important;
}

.drawer-metric.purple { background:#f1ebff !important; }
.drawer-metric.blue { background:#eef6ff !important; }
.drawer-metric.green { background:#edf9f3 !important; }
.drawer-metric.violet { background:#f5efff !important; }
.drawer-metric.teal { background:#eefafa !important; }
.drawer-metric.orange { background:#fff7e8 !important; }

.drawer-chart-card {
  margin-top:8px !important;

