  display:inline-flex !important;

  align-items:center !important;

  justify-content:center !important;

  gap:5px !important;

  border-radius:7px !important;

  font-size:7px !important;

  font-weight:900 !important;

  cursor:pointer !important;
}

.edit-action {
  border:1px solid #7040df !important;

  background:#7040df !important;

  color:#fff !important;
}

.student-action {
  border:1px solid #d8e0e7 !important;

  background:#fff !important;

  color:#587087 !important;
}


/* =========================================================
   POPUPS
   ========================================================= */

.popup-backdrop {
  position:fixed !important;

  inset:0 !important;

  padding:18px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  background:rgba(13,10,28,.42) !important;

  backdrop-filter:blur(2px) !important;

  z-index:1300 !important;
}

.student-popup,
.edit-modal {
  width:min(760px,94vw) !important;

  max-height:88vh !important;

  display:flex !important;

  flex-direction:column !important;

  overflow:hidden !important;

  border:1px solid #dce4eb !important;

  border-radius:14px !important;

  background:#fff !important;

  box-shadow:
    0 24px 60px rgba(17,25,39,.20) !important;
}

.popup-header {
  flex:0 0 73px !important;

  min-height:73px !important;

  padding:12px 14px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  border-bottom:1px solid #e4e9ee !important;

  background:
    linear-gradient(
      110deg,
      #f5f1ff,
      #f7fbff
    ) !important;
}

.popup-person {
  display:flex !important;

  align-items:center !important;

  gap:9px !important;
}

.popup-avatar {
  width:42px !important;

  height:42px !important;

  min-width:42px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border-radius:50% !important;

  background:#eee8ff !important;

  color:#7040df !important;

  font-size:8px !important;

  font-weight:950 !important;
}

.popup-header > div > span,
.popup-person > div > span {
  display:block !important;

  color:#7040df !important;

  font-size:6px !important;

  font-weight:950 !important;

  letter-spacing:.8px !important;
}

.popup-header h2 {
  margin:3px 0 0 !important;

  color:#26394e !important;

  font-size:15px !important;

  font-weight:950 !important;
}

.popup-header small {
  display:block !important;

  margin-top:3px !important;

  color:#8f9ba6 !important;

  font-size:6px !important;
}

.popup-close {
  width:32px !important;

  height:32px !important;

  min-width:32px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  border:1px solid #dce4eb !important;

  border-radius:8px !important;

  background:#fff !important;

  color:#6e7d8c !important;

  cursor:pointer !important;
}

.popup-close:hover {
  background:#f7f3ff !important;

  color:#7040df !important;
}

.popup-summary {
  padding:11px !important;

  display:grid !important;

  grid-template-columns:
    repeat(3,1fr) !important;

  gap:6px !important;
}

.popup-summary > div {
  padding:8px !important;

  border:1px solid #e3e8ed !important;

  border-radius:7px !important;

  background:#fafbfd !important;
}

.popup-summary span {
  display:block !important;

  color:#929da7 !important;

  font-size:5px !important;

  font-weight:950 !important;
}

.popup-summary strong {
  display:block !important;

  margin-top:3px !important;

  color:#35495e !important;

  font-size:7px !important;
}

.popup-history {
  flex:1 !important;

  min-height:0 !important;

  padding:0 11px 12px !important;

  overflow:auto !important;
}

.popup-history-header {
  padding:8px 0 !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  border-bottom:1px solid #e7ebef !important;
}

.popup-history-header span {
  color:#7040df !important;

  font-size:6px !important;

  font-weight:950 !important;

  letter-spacing:.7px !important;
}

.popup-history-header strong {
  color:#8b98a3 !important;

  font-size:6px !important;
}

.popup-history-row {
  min-height:46px !important;

  padding:7px 0 !important;

  display:grid !important;

  grid-template-columns:
    1.5fr .7fr .6fr 30px !important;

  gap:7px !important;

  align-items:center !important;

  border-bottom:1px solid #edf1f4 !important;
}

.history-assessment {
  min-width:0 !important;

  display:flex !important;

  flex-direction:column !important;
}

.history-assessment strong {
  color:#405469 !important;

  font-size:7px !important;
}

.history-assessment small {
  margin-top:2px !important;

  color:#99a4ae !important;

  font-size:6px !important;
}

.history-edit {
  width:28px !important;

  height:28px !important;

  border:1px solid #dce4eb !important;

  border-radius:7px !important;

  background:#fff !important;

  color:#6b7d8d !important;

  cursor:pointer !important;
}

.popup-empty {
  padding:25px !important;

  text-align:center !important;

  color:#929da7 !important;

  font-size:8px !important;
}


/* =========================================================
   EDIT MODAL
   ========================================================= */

.edit-body {
  flex:1 !important;

  min-height:0 !important;

  padding:13px !important;

  overflow:auto !important;
}

.edit-grid {
  display:grid !important;

  grid-template-columns:
    1fr 1fr !important;

  gap:8px !important;
}

.edit-field {
  display:flex !important;

  flex-direction:column !important;

  gap:4px !important;
}

.edit-field.full {
  grid-column:1 / -1 !important;
}

.edit-field label {
  color:#8794a1 !important;

  font-size:5px !important;

  font-weight:950 !important;

  letter-spacing:.7px !important;
}

.edit-field input,
.edit-field select,
.edit-field textarea {
  width:100% !important;

  min-height:34px !important;

  padding:0 8px !important;

  border:1px solid #d7e0e7 !important;

  border-radius:7px !important;

  background:#fff !important;

  color:#516577 !important;

  font-size:8px !important;

  outline:0 !important;
}

.edit-field textarea {
  min-height:70px !important;

  padding-top:8px !important;

  resize:vertical !important;
}

.edit-field input:focus,
.edit-field select:focus,
.edit-field textarea:focus {
  border-color:#a88ee0 !important;

  box-shadow:
    0 0 0 3px rgba(112,64,223,.07) !important;
}

.edit-error {
  margin-top:8px !important;

  padding:8px !important;

  border:1px solid #ffd1d1 !important;

  border-radius:7px !important;

  background:#fff2f2 !important;

  color:#c54545 !important;

  font-size:7px !important;
}

.edit-footer {
  flex:0 0 50px !important;

  min-height:50px !important;

  padding:8px 13px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:flex-end !important;

  gap:6px !important;

  border-top:1px solid #e4e9ee !important;

  background:#fafbfd !important;
}

.cancel-button,
.save-button {
  height:32px !important;

  padding:0 11px !important;

  border-radius:7px !important;

  font-size:7px !important;

  font-weight:900 !important;

  cursor:pointer !important;
}

.cancel-button {
  border:1px solid #d8e0e7 !important;

  background:#fff !important;

  color:#66798a !important;
}

.save-button {
  border:1px solid #7040df !important;

  background:#7040df !important;

  color:#fff !important;
}


/* =========================================================
   TOAST
   ========================================================= */

.toast {
  position:fixed !important;

  left:50% !important;

  bottom:16px !important;

  transform:translateX(-50%) !important;

  min-width:280px !important;

  max-width:500px !important;

  padding:9px 12px !important;

  display:flex !important;

  align-items:center !important;

  gap:8px !important;

  border-radius:8px !important;

  color:#fff !important;

  font-size:8px !important;

  box-shadow:
    0 12px 28px rgba(20,28,42,.20) !important;

  z-index:2000 !important;
}

.toast.success {
  background:#16845b !important;
}

.toast.error {
  background:#c94444 !important;
}

.toast span {
  flex:1 !important;
}

.toast button {
  width:22px !important;

  height:22px !important;

  border:0 !important;

  background:transparent !important;

  color:#fff !important;

  cursor:pointer !important;
}


/* =========================================================
   CHATBOT
   RESTORED TO data.chatbotWidget
   ========================================================= */

.campus360-chatbot {
  position:fixed !important;

  right:20px !important;

  bottom:18px !important;

  width:auto !important;

  height:auto !important;

  z-index:950 !important;
}


/* If ServiceNow renders the widget as a direct child */

body:has(.campus360-tpo-assessments) > sp-widget {
  position:fixed !important;

  right:20px !important;

  bottom:18px !important;

  z-index:950 !important;
}


/* =========================================================
   LOADING
   ========================================================= */

.fa-spin {
  animation:
    c360-spin 1s infinite linear !important;
}

@keyframes c360-spin {
  from {
    transform:rotate(0deg);
  }

  to {
    transform:rotate(359deg);
  }
}


/* =========================================================
   LARGE DESKTOP
   ========================================================= */

@media (max-width:1400px) {

  .tpo-sidebar {
    width:232px !important;
    min-width:232px !important;
    max-width:232px !important;
    flex-basis:232px !important;
  }

  .tpo-main {
    width:calc(100vw - 232px) !important;
    max-width:calc(100vw - 232px) !important;
  }

  .tpo-kpi-grid {
    grid-template-columns:
      repeat(5,minmax(120px,1fr)) !important;
  }

  .company-strip-stat {
    flex-basis:88px !important;
    width:88px !important;
    min-width:88px !important;
  }
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width:1100px) {

  .tpo-sidebar {
    width:215px !important;
    min-width:215px !important;
    max-width:215px !important;
    flex-basis:215px !important;
  }

  .tpo-main {
    width:calc(100vw - 215px) !important;
    max-width:calc(100vw - 215px) !important;
  }

  .tpo-top-profile-info {
    display:none !important;
  }

  .tpo-page-header p {
    display:none !important;
  }

  .tpo-filter-card {
    overflow-x:auto !important;
  }

  .tpo-kpi-grid {
    overflow-x:auto !important;
  }

  .tpo-kpi-card {
    min-width:145px !important;
  }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width:820px) {

  .campus360-tpo-assessments {
    display:block !important;
  }

  .tpo-sidebar {
    position:fixed !important;

    top:0 !important;
    left:0 !important;
    bottom:0 !important;

    width:225px !important;
    min-width:225px !important;
    max-width:225px !important;

    flex-basis:225px !important;

    transform:translateX(-100%) !important;

    transition:
      transform .22s ease !important;

    z-index:2000 !important;
  }

  .tpo-sidebar.open {
    transform:translateX(0) !important;
  }

  .tpo-main {
    width:100vw !important;
    max-width:100vw !important;
  }

  .tpo-topbar {
    padding:0 11px !important;
  }

  .tpo-breadcrumb {
    min-width:0 !important;

    height:auto !important;

    padding:0 !important;

    background:transparent !important;
  }

  .tpo-breadcrumb span {
    font-size:7px !important;
  }

  .tpo-breadcrumb strong {
    font-size:14px !important;
  }

  .tpo-content {
    height:calc(100vh - 74px) !important;

    max-height:none !important;

    overflow-y:auto !important;
  }

  .tpo-page-header {
    height:auto !important;

    min-height:105px !important;

    flex-direction:column !important;

    align-items:flex-start !important;
  }

  .page-header-actions {
    width:100% !important;

    justify-content:flex-start !important;
  }

  .tpo-kpi-grid {
    display:flex !important;

    overflow-x:auto !important;
  }

  .tpo-kpi-card {
    min-width:155px !important;
  }

  .tpo-filter-card {
    flex-wrap:wrap !important;

    height:auto !important;

    min-height:58px !important;

    overflow:visible !important;
  }

  .search-box {
    min-width:100% !important;

    flex-basis:100% !important;
  }

  .filter-field,
  .filter-field.company-field {
    flex:1 1 145px !important;

    width:auto !important;
  }

  .company-strip {
    max-width:100% !important;
  }

  .floating-drawer {
    width:94vw !important;

    max-width:94vw !important;
  }

  .drawer-metric-grid {
    grid-template-columns:
      repeat(2,1fr) !important;
  }

  .popup-summary {
    grid-template-columns:
      repeat(2,1fr) !important;
  }

  .edit-grid {
    grid-template-columns:1fr !important;
  }

  .edit-field.full {
