  }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width:560px) {

  .tpo-top-profile {
    margin-left:0 !important;
  }

  .tpo-top-profile-info,
  .tpo-top-chevron {
    display:none !important;
  }

  .tpo-page-header h1 {
    font-size:22px !important;
  }

  .header-action {
    padding:0 8px !important;
  }

  .popup-summary {
    grid-template-columns:1fr !important;
  }

  .drawer-status-grid {
    grid-template-columns:
      repeat(2,1fr) !important;
  }
}

sp_widget.script:
(function() {

    /* =====================================================
       TABLES
       ===================================================== */

    var ASSESSMENT =
        'x_snc_campus360_student_assessment';

    var APPLICATION =
        'x_snc_campus360_student_application';

    var OPPORTUNITY =
        'x_snc_campus360_placement_opportunity';

    var COMPANY =
        'x_snc_campus360_company_master';

    var INTERVIEW =
        'x_snc_campus360_recruiter_interview';

    var OUTCOME =
        'x_snc_campus360_placement_outcome';


    /* =====================================================
       DEFAULT DATA
       ===================================================== */

    data.rows = [];
    data.studentRows = [];

    data.companyChoices = [];
    data.resultChoices = [];
    data.typeChoices = [];
    data.statusChoices = [];

    data.studentChoices = [];
    data.opportunityChoices = [];

    data.studentFilterChoices = {
        application: [],
        interview: [],
        offer: [],
        assessment: []
    };

    data.summary = {
        total: 0,
        passed: 0,
        failed: 0,
        pending: 0,
        averageScore: 0
    };

    data.error = '';
    data.success = '';


    var action =
        String(
            input &&
            input.action
                ? input.action
                : ''
        );


    /* =====================================================
       HELPERS
       ===================================================== */

    function valid(gr, field) {

        return (
            gr &&
            gr.isValidField(field)
        );

    }


    function value(gr, field) {

        if (
            !valid(gr, field)
        ) {

            return '';

        }

        return String(
            gr.getValue(field) || ''
        );

    }


    function display(gr, field) {

        if (
            !valid(gr, field)
        ) {

            return '';

        }

        return String(
            gr.getDisplayValue(field) || ''
        );

    }


    function setValue(
        gr,
        field,
        val
    ) {

        if (
            !valid(gr, field)
        ) {

            return;

        }

        gr.setValue(
            field,
            val === null ||
            val === undefined
                ? ''
                : val
        );

    }


    function firstField(
        gr,
        fields
    ) {

        var i;

        for (
            i = 0;
            i < fields.length;
            i++
        ) {

            if (
                valid(
                    gr,
                    fields[i]
                )
            ) {

                return fields[i];

            }

        }

        return '';

    }


    function lower(
        val
    ) {

        return String(
            val || ''
        )
        .replace(
            /^\s+|\s+$/g,
            ''
        )
        .toLowerCase();

    }


    function initials(
        name
    ) {

        var text =
            String(
                name || ''
            )
            .replace(
                /^\s+|\s+$/g,
                ''
            );


        if (
            !text
        ) {

            return 'ST';

        }


        var p =
            text.split(
                /\s+/
            );


        if (
            p.length === 1
        ) {

            return p[0]
                .substring(0,2)
                .toUpperCase();

        }


        return (
            p[0].charAt(0) +
            p[p.length - 1].charAt(0)
        ).toUpperCase();

    }


    function dateDisplay(
        raw
    ) {

        if (
            !raw
        ) {

            return '';

        }


        var p =
            String(raw).split('-');


        if (
            p.length !== 3
        ) {

            return String(raw);

        }


        var months = [
            'Jan','Feb','Mar','Apr',
            'May','Jun','Jul','Aug',
            'Sep','Oct','Nov','Dec'
        ];


        var month =
            parseInt(
                p[1],
                10
            );


        var day =
            parseInt(
                p[2],
                10
            );


        if (
            isNaN(month) ||
            isNaN(day)
        ) {

            return raw;

        }


        return (
            day < 10
                ? '0' + day
                : day
        ) +
        ' ' +
        months[month - 1] +
        ' ' +
        p[0];

    }


    function choiceLabel(
        table,
        field,
        val
    ) {

        if (
            !val
        ) {

            return '';

        }


        var c =
            new GlideRecord(
                'sys_choice'
            );


        c.addQuery(
            'name',
            table
        );

        c.addQuery(
            'element',
            field
        );

        c.addQuery(
            'value',
            val
        );

        c.setLimit(1);

        c.query();


        if (
            c.next()
        ) {

            return String(
                c.getValue(
                    'label'
                ) ||
                val
            );

        }


        return String(val);

    }


    function loadChoices(
        table,
        field
    ) {

        var arr = [];


        var gr =
            new GlideRecord(
                'sys_choice'
            );


        gr.addQuery(
            'name',
            table
        );

        gr.addQuery(
            'element',
            field
        );

        gr.addQuery(
            'inactive',
            false
        );

        gr.orderBy(
            'sequence'
        );

        gr.query();


        while (
            gr.next()
        ) {

            arr.push({

                value:
                    String(
                        gr.getValue(
                            'value'
                        ) || ''
                    ),

                label:
                    String(
                        gr.getValue(
                            'label'
                        ) ||
                        gr.getValue(
                            'value'
                        ) ||
                        ''
                    )

            });

        }


        return arr;

    }


    /* =====================================================
       STUDENT CACHE
       ===================================================== */

    var studentCache = {};


    function studentInfo(
        sysId,
        displayName
    ) {

        if (
            !sysId
        ) {

            return {

                sys_id: '',

                student_id: '',

                student_name:
                    displayName || '',

                initials:
                    initials(
                        displayName
                    )

            };

        }


        if (
            studentCache[
                sysId
            ]
        ) {

            return studentCache[
                sysId
            ];

        }


        var result = {

            sys_id:
                sysId,

            student_id:
                '',

            student_name:
                displayName || '',

            initials:
                initials(
                    displayName
                )

        };


        var gr =
            new GlideRecord(
                'x_snc_campus360_student_master'
            );


        if (
            gr.get(
                sysId
            )
        ) {

            var idField =
                firstField(
                    gr,
                    [
                        'student_id',
                        'student_number',
                        'registration_number',
                        'u_student_id'
                    ]
                );


            var nameField =
                firstField(
                    gr,
                    [
                        'student_name',
                        'name',
                        'full_name',
                        'u_student_name'
                    ]
                );


            if (
                idField
            ) {

                result.student_id =
                    value(
                        gr,
                        idField
                    );

            }


            if (
                nameField
            ) {

                result.student_name =
                    value(
                        gr,
                        nameField
                    );

            }


            if (
                !result.student_name
            ) {

                result.student_name =
                    String(
                        gr.getDisplayValue()
                        || ''
                    );

            }

        }


        result.initials =
            initials(
                result.student_name
            );


        studentCache[
            sysId
        ] =
            result;


        return result;

    }


    /* =====================================================
       COMPANY
       ===================================================== */

    var companyCache = {};


    function resolveCompany(
        sysId,
        identifier,
        name
    ) {

        var result = {

            sys_id:
                sysId || '',

            company_id:
                identifier || '',

            company_name:
                name || ''

        };


        var key =
            String(
                sysId ||
                identifier ||
                ''
            );


        if (
            companyCache[key]
        ) {

            return companyCache[key];

        }


        var gr =
            new GlideRecord(
                COMPANY
            );


        var found =
            false;


        if (
            sysId &&
            gr.get(sysId)
        ) {

            found = true;

        } else if (
            identifier
        ) {

            var idField =
                firstField(
                    gr,
                    [
                        'company_id',
                        'company_code',
                        'code',
                        'u_company_id'
                    ]
                );


            if (
                idField
            ) {

                gr.addQuery(
                    idField,
                    identifier
                );

                gr.setLimit(1);

                gr.query();


                if (
                    gr.next()
                ) {

                    found = true;

                }

            }

        }


        if (
            found
        ) {

            result.sys_id =
                String(
                    gr.getUniqueValue()
                );


            var cid =
                firstField(
                    gr,
                    [
                        'company_id',
                        'company_code',
                        'code',
                        'u_company_id'
                    ]
                );


            var cname =
                firstField(
                    gr,
                    [
                        'company_name',
                        'name',
                        'u_company_name'
                    ]
                );


            if (
                cid
            ) {

                result.company_id =
                    value(
                        gr,
                        cid
                    );

            }


            if (
                cname
            ) {

                result.company_name =
                    value(
                        gr,
                        cname
                    );

            }


            if (
                !result.company_name
            ) {

                result.company_name =
                    String(
                        gr.getDisplayValue()
                        || ''
                    );

            }

        }


        if (
            !result.company_name
        ) {

            result.company_name =
                result.company_id ||
                'Company Not Specified';

        }


        companyCache[key] =
            result;


        return result;

    }


    /* =====================================================
       OPPORTUNITY
       ===================================================== */

    var opportunityCache = {};


    function opportunityInfo(
        sysId,
        displayName
    ) {

        if (
            !sysId
        ) {

            return {

                sys_id: '',

                opportunity_id:
                    displayName || '',

                opportunity_name:
                    displayName || '',

                company_id: '',

                company_name: ''

            };

        }


        if (
            opportunityCache[
                sysId
            ]
        ) {

            return opportunityCache[
                sysId
            ];

        }


        var result = {

            sys_id:
                sysId,

            opportunity_id:
                '',

            opportunity_name:
                '',

            company_id:
                '',

            company_name:
                ''

        };


        var gr =
            new GlideRecord(
                OPPORTUNITY
            );


        if (
            gr.get(sysId)
        ) {

            var idField =
                firstField(
                    gr,
                    [
                        'opportunity_id',
                        'opportunity_number',
                        'number',
                        'u_opportunity_id'
                    ]
                );


            var nameField =
                firstField(
                    gr,
                    [
                        'opportunity_name',
                        'name',
                        'title',
                        'u_opportunity_name'
                    ]
                );


            if (
                idField
            ) {

                result.opportunity_id =
                    value(
                        gr,
                        idField
                    );

            }


            if (
                nameField
            ) {

                result.opportunity_name =
                    value(
                        gr,
                        nameField
                    );

            }


            if (
                !result.opportunity_name
            ) {

                result.opportunity_name =
                    String(
                        gr.getDisplayValue()
                        || ''
                    );

            }


            var companyField =
                firstField(
                    gr,
                    [
                        'company',
                        'company_ref'
                    ]
                );


            if (
                companyField
            ) {

                var companySysId =
                    value(
                        gr,
                        companyField
                    );


                var companyDisplay =
                    display(
                        gr,
                        companyField
                    );


                var resolved =
                    resolveCompany(
                        companySysId,
                        companyDisplay,
                        companyDisplay
                    );


                result.company_id =
                    resolved.company_id;


                result.company_name =
                    resolved.company_name;

            }


            if (
                !result.company_id
            ) {

                var directCompanyId =
                    firstField(
                        gr,
                        [
                            'company_id',
                            'company_code',
                            'u_company_id'
                        ]
                    );


                if (
                    directCompanyId
                ) {

                    result.company_id =
                        value(
                            gr,
                            directCompanyId
                        );

                }

            }


            if (
                !result.company_name
            ) {

                var directCompanyName =
                    firstField(
                        gr,
                        [
                            'company_name',
                            'name',
                            'u_company_name'
                        ]
                    );


                if (
                    directCompanyName
                ) {

                    result.company_name =
                        value(
                            gr,
                            directCompanyName
                        );

                }

            }

        }


        if (
            !result.opportunity_id
        ) {

            result.opportunity_id =
                displayName ||
                sysId;

        }


        if (
            !result.company_name
        ) {

            result.company_name =
                result.company_id ||
                'Company Not Specified';

        }


        opportunityCache[
            sysId
        ] =
            result;


        return result;

    }


    /* =====================================================
       ASSESSMENT ROW
       ===================================================== */

    function assessmentRow(
        gr
    ) {

        var studentSysId =
            value(
                gr,
                'student'
            );


        var studentDisplay =
            display(
                gr,
                'student'
            );


        var student =
            studentInfo(
                studentSysId,
                studentDisplay
            );


        if (
            studentDisplay &&
            !student.student_name
        ) {

            student.student_name =
                studentDisplay;

            student.initials =
                initials(
                    studentDisplay
                );

        }


        var opportunitySysId =
            value(
                gr,
                'opportunity'
            );


        var opportunity =
            opportunityInfo(
                opportunitySysId,
                display(
                    gr,
                    'opportunity'
                )
            );


        var directCompany =
            firstField(
                gr,
                [
                    'company',
                    'company_ref'
                ]
            );


        if (
            directCompany
        ) {

            var c =
                resolveCompany(
                    value(
                        gr,
                        directCompany
                    ),
                    display(
                        gr,
                        directCompany
                    ),
                    display(
                        gr,
                        directCompany
                    )
                );


            opportunity.company_id =
                c.company_id;

            opportunity.company_name =
                c.company_name;

        }


        var typeValue =
            value(
                gr,
                'assessment_type'
            );


        var resultValue =
            value(
                gr,
                'result'
            );


        var statusValue =
            value(
                gr,
                'status'
            );


        var max =
            parseFloat(
                value(
                    gr,
                    'maximum_score'
                )
            );


        var score =
            parseFloat(
                value(
                    gr,
                    'score'
                )
            );


        if (
            isNaN(max)
        ) {

            max = 0;

        }


        if (
            isNaN(score)
        ) {

            score = 0;

        }


        var pct = 0;


        if (
            max > 0
        ) {

            pct =
                Math.round(
                    (
                        score /
                        max
                    ) *
                    100
                );

        }


        return {

            sys_id:
                String(
                    gr.getUniqueValue()
                ),

            assessment_id:
                value(
                    gr,
                    'assessment_id'
                ),

            assessment_date_raw:
                value(
                    gr,
                    'assessment_date'
                ),

            assessment_date:
                dateDisplay(
                    value(
                        gr,
                        'assessment_date'
                    )
                ),

            assessment_name:
                value(
                    gr,
                    'assessment_name'
                ),

            assessment_type_value:
                typeValue,

            assessment_type:
                choiceLabel(
                    ASSESSMENT,
                    'assessment_type',
                    typeValue
                ),

            maximum_score:
                max,

            opportunity_value:
                opportunitySysId,

            opportunity:
                opportunity.opportunity_id,

            opportunity_title:
                opportunity.opportunity_name,

            company_id:
                opportunity.company_id,

            company_name:
                opportunity.company_name,

            remarks:
                value(
                    gr,
                    'remarks'
                ),

            result_value:
                resultValue,

            result:
                choiceLabel(
                    ASSESSMENT,
                    'result',
                    resultValue
                ),

            score:
                score,

            scorePercentage:
                Math.max(
                    0,
                    Math.min(
                        100,
                        pct
                    )
                ),

            scoreDisplay:
                max > 0
                    ? score + '/' + max
                    : String(score),

            student:
                studentSysId,

            student_name:
                student.student_name,

            student_id:
                student.student_id,

            student_initials:
                student.initials,

            duration:
                value(
                    gr,
                    'duration'
                ),

            status_value:
                statusValue,

            status:
                choiceLabel(
                    ASSESSMENT,
                    'status',
                    statusValue
                )

        };

    }


    /* =====================================================
       LOAD ASSESSMENTS
       ===================================================== */

    function loadAssessments() {

        data.rows = [];


        var gr =
            new GlideRecord(
                ASSESSMENT
            );


        if (
            valid(
                gr,
                'assessment_date'
            )
        ) {

            gr.orderByDesc(
                'assessment_date'
            );

        }


        gr.orderByDesc(
            'sys_created_on'
        );


        gr.setLimit(
            5000
        );


        gr.query();


        while (
            gr.next()
        ) {

            data.rows.push(
                assessmentRow(
                    gr
                )
            );

        }

    }


    /* =====================================================
       COMPANY DROPDOWN
       ===================================================== */

    function loadCompanyChoices() {

        var map = {};


        var gr =
            new GlideRecord(
                COMPANY
            );


        gr.setLimit(
            3000
        );


        gr.query();


        while (
            gr.next()
        ) {

            var idField =
                firstField(
                    gr,
                    [
                        'company_id',
                        'company_code',
                        'code',
                        'u_company_id'
                    ]
                );


            var nameField =
                firstField(
                    gr,
                    [
                        'company_name',
                        'name',
                        'u_company_name'
                    ]
                );


            var id =
                idField
                    ? value(
                        gr,
                        idField
                      )
                    : String(
                        gr.getUniqueValue()
                      );


            var name =
                nameField
                    ? value(
                        gr,
                        nameField
                      )
                    : String(
                        gr.getDisplayValue()
                        || id
                      );


            if (
                id
            ) {

                map[id] = {

                    value:
                        id,

                    label:
                        name || id

                };

            }

        }


        var i;


        for (
            i = 0;
            i < data.rows.length;
            i++
        ) {

            var row =
                data.rows[i];


            if (
                row.company_id
            ) {

                map[
                    row.company_id
                ] = {

                    value:
                        row.company_id,

                    label:
                        row.company_name ||
                        row.company_id

                };

            }

        }


        data.companyChoices = [];


        var key;


        for (
            key in map
        ) {

            if (
                map.hasOwnProperty(
                    key
                )
            ) {

                data.companyChoices.push(
                    map[key]
                );

            }

        }


        data.companyChoices.sort(
            function(a,b) {

                return String(
                    a.label
                )
                .localeCompare(
                    String(
                        b.label
                    )
                );

            }
        );

    }


    /* =====================================================
       REFERENCE CHOICES
       ===================================================== */

    function buildReferenceChoices() {

        var students = {};
        var opportunities = {};


        var i;


        for (
            i = 0;
            i < data.rows.length;
            i++
        ) {

            var row =
                data.rows[i];


            if (
                row.student
            ) {

                students[
                    row.student
                ] = {

                    value:
                        row.student,

                    label:
                        (
                            row.student_id
                                ? row.student_id +
                                  ' - '
                                : ''
                        ) +
                        (
                            row.student_name ||
                            'Student'
                        )

                };

            }


            if (
                row.opportunity_value
            ) {

                opportunities[
                    row.opportunity_value
                ] = {

                    value:
                        row.opportunity_value,

                    label:
                        (
                            row.opportunity ||
                            row.opportunity_title ||
                            'Opportunity'
                        ) +
                        (
                            row.company_name
                                ? ' - ' +
                                  row.company_name
                                : ''
                        )

                };

            }

        }


        data.studentChoices = [];
        data.opportunityChoices = [];


        var key;


        for (
            key in students
        ) {

            if (
                students.hasOwnProperty(
                    key
                )
            ) {

                data.studentChoices.push(
                    students[key]
                );

            }

        }


        for (
            key in opportunities
        ) {

            if (
                opportunities.hasOwnProperty(
                    key
                )
            ) {

                data.opportunityChoices.push(
                    opportunities[key]
                );

            }

        }

    }


    /* =====================================================
       INTERVIEWS
       ===================================================== */

    function buildInterviewMap() {

        var map = {};


        var gr =
            new GlideRecord(
                INTERVIEW
            );


        if (
            !gr.isValid()
        ) {

            return map;

        }


        gr.setLimit(
            10000
        );


        gr.query();


        while (
            gr.next()
        ) {

            var student =
                value(
                    gr,
                    'student'
                );


            var opportunity =
                value(
                    gr,
                    'opportunity'
                );


            var statusField =
                firstField(
                    gr,
                    [
                        'interview_status',
                        'status',
                        'result',
                        'interview_result'
                    ]
                );


            var status =
                statusField
                    ? (
                        display(
                            gr,
                            statusField
                        ) ||
                        value(
                            gr,
                            statusField
                        )
                      )
                    : 'Interview Activity';


            if (
                student &&
                opportunity
            ) {

                map[
                    student +
                    '|' +
                    opportunity
                ] =
                    status;

            }


            if (
                student &&
                !map[
                    student +
                    '|student'
                ]
            ) {

                map[
                    student +
                    '|student'
                ] =
                    status;

            }

        }


        return map;

    }


    /* =====================================================
       OUTCOME
       ===================================================== */

    function buildOutcomeMap() {

        var map = {};


        var gr =
            new GlideRecord(
                OUTCOME
            );


        if (
            !gr.isValid()
        ) {

            return map;

        }


        gr.setLimit(
            10000
        );


        gr.query();


        while (
            gr.next()
        ) {

            var student =
                value(
                    gr,
                    'student'
                );


            var opportunity =
                value(
                    gr,
                    'opportunity'
                );


            var statusField =
                firstField(
                    gr,
                    [
                        'offer_status',
                        'outcome',
                        'placement_status',
                        'status',
                        'offer_result'
                    ]
                );


            var status =
                statusField
                    ? (
                        display(
                            gr,
                            statusField
                        ) ||
                        value(
                            gr,
                            statusField
                        )
                      )
                    : 'Offer Activity';


            if (
                student &&
                opportunity
            ) {

                map[
                    student +
                    '|' +
                    opportunity
                ] =
                    status;

            }


            if (
                student &&
                !map[
                    student +
                    '|student'
                ]
            ) {

                map[
                    student +
                    '|student'
                ] =
                    status;

            }

        }


        return map;

    }


    /* =====================================================
       STUDENT ROWS
       ===================================================== */

    function loadStudentRows() {

        data.studentRows = [];


        var interviews =
            buildInterviewMap();


        var outcomes =
            buildOutcomeMap();


        var assessments = {};


        var i;


        for (
            i = 0;
            i < data.rows.length;
            i++
        ) {

            var assessment =
                data.rows[i];


            var key =
                (
                    assessment.student ||
                    ''
                ) +
                '|' +
                (
                    assessment.opportunity_value ||
                    ''
                );


            assessments[
                key
            ] =
                assessment;

        }


        var application =
            new GlideRecord(
                APPLICATION
            );


        if (
            !application.isValid()
        ) {

            buildAssessmentOnlyStudents(
                assessments,
                {}
            );

            buildStudentFilters();

            return;

        }


        application.setLimit(
            10000
        );


        application.query();


        var seen = {};


        while (
            application.next()
        ) {

            var studentSysId =
                value(
                    application,
                    'student'
                );


            if (
                !studentSysId
            ) {

                continue;

            }


            var student =
                studentInfo(
                    studentSysId,
                    display(
                        application,
                        'student'
                    )
                );


            var opportunitySysId =
                value(
                    application,
                    'opportunity'
                );


            var opportunity =
                opportunityInfo(
                    opportunitySysId,
                    display(
                        application,
                        'opportunity'
                    )
                );


            var applicationField =
                firstField(
                    application,
                    [
                        'application_status',
                        'status',
                        'stage',
                        'application_stage'
                    ]
                );


            var applicationStatus =
                applicationField
                    ? (
                        display(
                            application,
                            applicationField
                        ) ||
                        value(
                            application,
                            applicationField
                        )
                      )
                    : 'Applied';


            var assessmentKey =
                studentSysId +
                '|' +
                opportunitySysId;


            var assessment =
                assessments[
                    assessmentKey
                ];


            if (
                !assessment
            ) {

                var assessmentKey2;


                for (
                    assessmentKey2 in
                    assessments
                ) {

                    if (
                        assessments.hasOwnProperty(
                            assessmentKey2
                        ) &&
                        assessmentKey2.indexOf(
                            studentSysId + '|'
                        ) === 0
                    ) {

                        assessment =
                            assessments[
                                assessmentKey2
                            ];

                        break;

                    }

                }

            }


            data.studentRows.push({

                row_key:
                    String(
                        application.getUniqueValue()
                    ),

                has_application:
                    true,

                student_sys_id:
                    studentSysId,

                student_name:
                    student.student_name ||
                    'Student',

                student_id:
                    student.student_id ||
                    '',

                initials:
                    student.initials,

                company_id:
                    opportunity.company_id,

                company_name:
                    opportunity.company_name,

                opportunity:
                    opportunity.opportunity_id ||
                    display(
                        application,
                        'opportunity'
                    ),

                opportunity_sys_id:
                    opportunitySysId,

                application_status:
                    applicationStatus ||
                    'Applied',

                interview_status:
                    interviews[
                        studentSysId +
                        '|' +
                        opportunitySysId
                    ] ||
                    interviews[
                        studentSysId +
                        '|student'
                    ] ||
                    '—',

                offer_status:
                    outcomes[
                        studentSysId +
                        '|' +
                        opportunitySysId
                    ] ||
                    outcomes[
                        studentSysId +
                        '|student'
                    ] ||
                    '—',

                assessment_sys_id:
                    assessment
                        ? assessment.sys_id
                        : '',

                assessment_result:
                    assessment
                        ? assessment.result
                        : '',

                assessment_result_value:
                    assessment
                        ? assessment.result_value
                        : '',

                assessment_type:
                    assessment
                        ? assessment.assessment_type
                        : '',

                assessment_type_value:
                    assessment
                        ? assessment.assessment_type_value
                        : '',

                assessment_status:
                    assessment
                        ? assessment.status
                        : '',

                assessment_status_value:
                    assessment
                        ? assessment.status_value
                        : '',

                assessment_score:
                    assessment
                        ? assessment.score
                        : null,

                maximum_score:
                    assessment
                        ? assessment.maximum_score
                        : 0

            });


            seen[
                assessmentKey
            ] =
                true;

        }


        buildAssessmentOnlyStudents(
            assessments,
            seen
        );


        buildStudentFilters();

    }


    function buildAssessmentOnlyStudents(
        assessments,
        seen
    ) {

        var key;


        for (
            key in assessments
        ) {

            if (
                !assessments.hasOwnProperty(
                    key
                )
            ) {

                continue;

            }


            if (
                seen[key]
            ) {

                continue;

            }


            var row =
                assessments[key];


            data.studentRows.push({

                row_key:
                    'assessment_' +
                    row.sys_id,

                has_application:
                    false,

                student_sys_id:
                    row.student,

                student_name:
                    row.student_name ||
                    'Student',

                student_id:
                    row.student_id ||
                    '',

                initials:
                    row.student_initials ||
                    'ST',

                company_id:
                    row.company_id,

                company_name:
                    row.company_name,

                opportunity:
                    row.opportunity ||
                    row.opportunity_title ||
                    'Opportunity',

                opportunity_sys_id:
                    row.opportunity_value,

                application_status:
                    'No application record',

                interview_status:
                    '—',

                offer_status:
                    '—',

                assessment_sys_id:
                    row.sys_id,

                assessment_result:
                    row.result,

                assessment_result_value:
                    row.result_value,

                assessment_type:
                    row.assessment_type,

                assessment_type_value:
                    row.assessment_type_value,

                assessment_status:
                    row.status,

                assessment_status_value:
                    row.status_value,

                assessment_score:
                    row.score,

                maximum_score:
                    row.maximum_score

            });

        }

    }


    function buildStudentFilters() {

        var application = {};
        var interview = {};
        var offer = {};
        var assessment = {};


        var i;


        for (
            i = 0;
            i < data.studentRows.length;
            i++
        ) {

            var row =
                data.studentRows[i];


            if (
                row.application_status
            ) {

                application[
                    row.application_status
                ] = true;

            }


            if (
                row.interview_status
            ) {

                interview[
                    row.interview_status
                ] = true;

            }


            if (
                row.offer_status
            ) {

                offer[
                    row.offer_status
                ] = true;

            }


            if (
                row.assessment_result
            ) {

                assessment[
                    row.assessment_result
                ] = true;

            }

        }


        data.studentFilterChoices = {

            application:
                mapKeys(application),

            interview:
                mapKeys(interview),

            offer:
                mapKeys(offer),

            assessment:
                mapKeys(assessment)

        };

    }


    function mapKeys(
        map
    ) {

        var arr = [];
        var key;


        for (
            key in map
        ) {

            if (
                map.hasOwnProperty(
                    key
                )
            ) {

                arr.push(
                    key
                );

            }

        }


        arr.sort(
            function(a,b) {

                return String(a)
                    .localeCompare(
                        String(b)
                    );

            }
        );


        return arr;

    }


    /* =====================================================
       EDIT
       ===================================================== */

    function saveEdit() {

        var form =
            input.form ||
            {};


        var sysId =
            String(
                form.sys_id ||
                ''
            );


        if (
            !sysId
        ) {

            data.error =
                'Only existing assessments can be edited.';

            return;

        }


        var gr =
            new GlideRecord(
                ASSESSMENT
            );


        if (
            !gr.get(
                sysId
            )
        ) {

            data.error =
                'Assessment record not found.';

            return;

        }


        if (
            !form.assessment_id ||
            !form.assessment_name ||
            !form.assessment_date
        ) {

            data.error =
                'Assessment date, ID and name are required.';

            return;

        }


        var duplicate =
            new GlideRecord(
                ASSESSMENT
            );


        duplicate.addQuery(
            'assessment_id',
            String(
                form.assessment_id
            )
        );


        duplicate.addQuery(
            'sys_id',
            '!=',
            sysId
        );


        duplicate.setLimit(1);

        duplicate.query();


        if (
            duplicate.next()
        ) {

            data.error =
                'Another assessment already uses this Assessment ID.';

            return;

        }


        var max =
            Number(
                form.maximum_score
            );


        var score =
            Number(
                form.score
            );


        if (
            !isNaN(max) &&
            !isNaN(score) &&
            score > max
        ) {

            data.error =
                'Score cannot be greater than maximum score.';

            return;

        }


        setValue(
            gr,
            'assessment_date',
            form.assessment_date
        );


        setValue(
            gr,
            'assessment_id',
            form.assessment_id
        );


        setValue(
            gr,
            'assessment_name',
            form.assessment_name
        );


        setValue(
            gr,
            'assessment_type',
            form.assessment_type || ''
        );


        setValue(
            gr,
            'maximum_score',
            form.maximum_score
        );


        setValue(
            gr,
            'student',
            form.student || ''
        );


        setValue(
            gr,
            'opportunity',
            form.opportunity || ''
        );


        setValue(
            gr,
            'result',
            form.result || ''
        );


        setValue(
            gr,
            'score',
            form.score
        );


        setValue(
            gr,
            'duration',
            form.duration
        );


        setValue(
            gr,
            'status',
            form.status || ''
        );


        setValue(
            gr,
            'remarks',
            form.remarks || ''
        );


        gr.update();


        data.success =
            'Assessment updated successfully.';


        loadAll();

    }


    /* =====================================================
       LOAD
       ===================================================== */

    function loadAll() {

        data.resultChoices =
            loadChoices(
                ASSESSMENT,
                'result'
            );


        data.typeChoices =
            loadChoices(
                ASSESSMENT,
                'assessment_type'
            );


        data.statusChoices =
            loadChoices(
                ASSESSMENT,
                'status'
            );


        if (
            !data.resultChoices.length
        ) {

            data.resultChoices = [

                {
                    value: 'passed',
                    label: 'Passed'
                },

                {
                    value: 'failed',
                    label: 'Failed'
                },

                {
                    value: 'pending',
                    label: 'Pending'
                }

            ];

        }


        if (
            !data.typeChoices.length
        ) {

            data.typeChoices = [

                {
                    value: 'technical',
                    label: 'Technical'
                },

                {
                    value: 'aptitude',
                    label: 'Aptitude'
                },

                {
                    value: 'domain',
                    label: 'Domain'
                },

                {
                    value: 'technical_aptitude',
                    label: 'Technical + Aptitude'
                }

            ];

        }


        if (
            !data.statusChoices.length
        ) {

            data.statusChoices = [

                {
                    value: 'draft',
                    label: 'Draft'
                },

                {
                    value: 'published',
                    label: 'Published'
                }

            ];

        }


        loadAssessments();

        loadCompanyChoices();

        buildReferenceChoices();

        loadStudentRows();

        buildSummary();

    }


    function buildSummary() {

        var passed = 0;
        var failed = 0;
        var pending = 0;

        var totalScore = 0;
        var scoreCount = 0;


        var i;


        for (
            i = 0;
            i < data.rows.length;
            i++
        ) {

            var row =
                data.rows[i];


            var result =
                lower(
                    row.result
                );


            if (
                result === 'passed'
            ) {

                passed++;

            } else if (
                result === 'failed'
            ) {

                failed++;

            } else if (
                result === 'pending'
            ) {

                pending++;

            }


            if (
                row.maximum_score > 0
            ) {

                totalScore +=
                    row.scorePercentage;

                scoreCount++;

            }

        }


        data.summary = {

            total:
                data.rows.length,

            passed:
                passed,

            failed:
                failed,

            pending:
                pending,

            averageScore:
                scoreCount
                    ? Math.round(
                        totalScore /
                        scoreCount
                      )
                    : 0

        };

    }


    /* =====================================================
       EXECUTE
       ===================================================== */

    if (
        action === 'edit'
    ) {

        saveEdit();

    } else {

        loadAll();

    }

})();
